    "ui.558": { ru: "Виден всем, кто сейчас в комнате · очищается, когда все закончат 🌸", en: "Visible to everyone currently in the room · clears when everyone finishes 🌸", uz: "Hozir xonadagi hammaga koʻrinadi · hamma tugatganda tozalanadi 🌸" },
    "ui.559": { ru: "Стоп", en: "Stop", uz: "Toʻxtatish" },
    "ui.560": { ru: "Цикл {cycle} из {total} — за работу! 🍅", en: "Cycle {cycle} of {total} — back to work! 🍅", uz: "{total} dan {cycle}-sikl — ishga! 🍅" },
    "ui.561": { ru: "{mins} мин засчитано · +{xp} XP 🌸", en: "{mins} min counted · +{xp} XP 🌸", uz: "{mins} daq hisobga olindi · +{xp} XP 🌸" },
    "ui.562": { ru: "Дождь", en: "Rain", uz: "Yomgʻir" },
    "ui.563": { ru: "Волны", en: "Waves", uz: "Toʻlqinlar" },
    "ui.564": { ru: "Камин", en: "Fireplace", uz: "Kamin" },
    "ui.565": { ru: "Бриз", en: "Breeze", uz: "Shabada" },
    "ui.566": { ru: "Пока тихо. Напиши первым — поддержите друг друга 🌸", en: "Quiet for now. Be the first to write — support each other 🌸", uz: "Hozircha jim. Birinchi boʻlib yoz — bir-biringizni qoʻllab-quvvatlang 🌸" },
    "ui.567": { ru: "Пока никого — будь первой! Когда друзья запустят таймер, ты увидишь их здесь 🌸", en: "No one yet — be the first! When friends start their timer, you'll see them here 🌸", uz: "Hozircha hech kim yoʻq — birinchi boʻl! Doʻstlaring taymer ishga tushirsa, ularni shu yerda koʻrasan 🌸" },
    "ui.568": { ru: "друг", en: "friend", uz: "doʻst" },
    "ui.569": { ru: "Гость", en: "Guest", uz: "Mehmon" },
