  // Версия сборки: держать В РУЧНУЮ синхронной с ?v= в index.html при каждом деплое
  // (те же 3 места — stylesheet/preload/script). Используется только для попапа
  // «доступно обновление» ниже — сама загрузка кода по-прежнему идёт через ?v=.
  const APP_VERSION = '20260716a';
  function showUpdateAvailableModal() {
    if (document.getElementById('update-avail-modal')) return;
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'update-avail-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:360px; text-align:center;">
        <div style="font-size:44px;">🌸✨</div>
        <div class="display" style="font-size:20px; color:var(--berry); margin-top:10px;">${t('update.title')}</div>
        <div style="font-size:12.5px; color:var(--soft); margin-top:8px; line-height:1.6;">${t('update.body')}</div>
        <button onclick="location.reload()" class="btn btn-primary btn-block" style="margin-top:16px;">${t('update.cta')}</button>
        <button onclick="this.closest('.modal-bg').remove()" class="btn btn-ghost btn-block" style="margin-top:8px;">${t('update.later')}</button>
      </div>`;
    document.body.appendChild(m);
  }

  function initFirebaseSync() {
    if (typeof _db === 'undefined') return;
    applyUStoreCloudSync();
    // Реальное состояние связи с Firebase — используется, чтобы снимать push-гейт по
    // таймауту ТОЛЬКО при настоящем офлайне (на медленной онлайн-сети ждём снапшот).
    try { _db.ref('.info/connected').on('value', s => { _fbConnected = !!s.val(); }); } catch (_) {}
    SHARED_KEYS.forEach(key => {
      let firstFire = true;
      _db.ref('shared/' + key).on('value', snap => {
        const val = snap.val();
        // Seed cloud from local on first fire if cloud is empty
        if (firstFire) {
          firstFire = false;
          if (val === null || val === undefined) {
            const local = Store.get(key, []);
            if (Array.isArray(local) && local.length > 0) {
              _db.ref('shared/' + key).set(local).catch(e => console.warn('seed shared/'+key+' failed:', e));
            }
            return;
          }
        }
        let data = [];
        if (val !== null && val !== undefined) {
          data = Array.isArray(val) ? val : Object.values(val);
        }
        _origStoreSet(key, data);
        if (key === 'customFeedPosts') renderCustomFeedPosts();
        if (key === 'customVideos') renderCustomVideos();
        if (key === 'customLessons') { renderCustomLessons(); renderHeroLesson(); renderLessonPath(); }
        if (key === 'topikMaterials' && document.getElementById('screen-topik')?.classList.contains('active')) renderTopik();
      });
    });
    // Нативный TTS: URL воркера, заданный Мади, раздаётся на все устройства.
    _db.ref('shared/config/ttsProxyUrl').on('value', snap => {
      const url = (snap.val() || '').toString().trim();
      try { if (url) localStorage.setItem('km_tts_proxy', url); else localStorage.removeItem('km_tts_proxy'); } catch (_) {}
      window.KM_TTS_PROXY_URL = url;
    });
    // Отметка версии (телеметрия деплоя): первый клиент с новой версией поднимает её
    // в облаке. САМА ПО СЕБЕ никого не дёргает — просьба 08.07: не показывать
    // «обновите страницу» при каждом пуше.
    const appVerRef = _db.ref('shared/config/appVersion');
    appVerRef.once('value').then(snap => {
      const remote = (snap.val() || '').toString();
      if (APP_VERSION > remote) appVerRef.set(APP_VERSION).catch(() => {});
    }).catch(() => {});
    // Оповещение об обновлении показывается ТОЛЬКО когда Мади нажмёт «Оповестить»
    // в админке (Школа → Обновление) — та кнопка пишет shared/config/promptVersion.
    // Формат YYYYMMDD+буква сравнивается строками корректно; один раз на версию.
    _db.ref('shared/config/promptVersion').on('value', snap => {
      const remote = (snap.val() || '').toString();
      if (!remote || !(remote > APP_VERSION) || isGuestish()) return;
      let seen = '';
      try { seen = localStorage.getItem('km_update_seen_v') || ''; } catch (_) {}
      if (seen === remote) return;
      try { localStorage.setItem('km_update_seen_v', remote); } catch (_) {}
      showUpdateAvailableModal();
    });
  }
  // ── Friends & Chat ──
  let _friendsCache = {};
  let _inboxCache = {};
  let _outgoingCache = {};
  let _groupsCache = {};   // gid -> {title, since} (my group chats, users/<me>/groups)
  let _usersDirCache = null;
  let _chatListenerOff = null;
  let _chatCurrentId = null;
  let _chatOtherUid = null;        // uid of the person in the open chat (for read receipts); gid for groups
  let _chatIsGroup = false;        // открыт групповой чат
  let _chatMembers = {};           // group: uid -> name (typing line + sender labels)
  let _chatReadMeta = {};          // chats/{id}/meta/read → { uid: lastReadTs }
  let _lastChatMsgs = {};          // last messages snapshot (so reactions/ticks re-render)
  let _chatReplyTo = null;         // { id, text, from, fromName } when replying
  // Telegram-Premium chat FX state
  let _chatSeenKeys = null;        // Set of message keys already painted (null = first paint, no entrance anim)
  let _chatPrevReactions = {};     // mid -> { uid: emoji } from the previous render (for burst diff)
  let _chatLastRenderedSig = null; // разметка прошлого рендера (без enter-классов) — гасит лишние innerHTML
  let _chatTyping = {};            // chats/{id}/meta/typing → { uid: ts } (other side typing)
  let _typingWriteAt = 0;          // throttle for my own typing writes
  let _typingClearTimer = null;    // clears my typing flag after a pause
  let _sendingFriendReq = new Set();
  function myUid() { return firebaseUserId(); }
  function myName() { const u = Store.get('user'); return (u && u.name) || t('friend.noName'); }
  function chatIdFor(a, b) { return [a, b].sort().join('__'); }

  function escHtml(s) {
    return String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  // Safe to drop inside a single-quoted JS string that itself lives inside a
  // double-quoted HTML attribute (e.g. onclick="fn('…')"). Escapes the JS-string
  // delimiter, backslashes, the attribute delimiter and line breaks.
  function jsStr(s) {
    return String(s == null ? '' : s)
      .replace(/\\/g, '\\\\')
      .replace(/'/g, "\\'")
      .replace(/"/g, '&quot;')
      .replace(/[\r\n]+/g, ' ');
  }

  let _dirReadyFlag = null; // null — ещё не спрашивали у облака
  // Справочник учеников не меняется поминутно (имя/фото/уровень), а живой
  // онлайн-статус в чате идёт отдельным heartbeat-путём — поэтому в пределах TTL
  // отдаём его прямо из localStorage БЕЗ единого обращения к сети: ученик может
  // открывать «Общение» весь день, а справочник скачается с сервера один раз.
  const DIR_CACHE_TTL_MS = 10 * 60 * 1000;
  async function loadUsersDirectory() {
    if (typeof _db === 'undefined') return {};
    try {
      // Третья волна трафика (14.07): у Мади справочник читал ПОЛНЫЙ узел `users`
      // (~1 МБ на 280 профилей) при каждом старте PWA — iOS перезагружает её
      // приложение почти при каждом возврате, и это стало главным расходом БД.
      // Чат-листу хватает тонкого usersPublic (имя/фото/email/level/stats-lite —
      // см. publicStatsLite), поэтому админ идёт тем же путём, что и ученицы.
      // Полные профили админ-панели качают сами по требованию с TTL
      // (loadAdminUsers/loadAdminStats).
      const cached = Store.get('usersDirCacheV1', null);
      if (cached && cached.data && (Date.now() - (cached.at || 0)) < DIR_CACHE_TTL_MS) {
        _dirReadyFlag = !!cached.dirReady;
        _usersDirCache = cached.data;
        return _usersDirCache;
      }
      if (_dirReadyFlag === null) {
        const f = await _db.ref('shared/config/dirReady').once('value');
        _dirReadyFlag = !!f.val();
      }
      // Ученикам хватает тонкого справочника — полный users (со всей статой и
      // прогрессом каждого) им скачивать незачем: это и было главной утечкой трафика.
      if (_dirReadyFlag) {
        try {
          const snap = await _db.ref('usersPublic').once('value');
          const val = snap.val();
          if (val && Object.keys(val).length) {
            _usersDirCache = val;
            Store.set('usersDirCacheV1', { at: Date.now(), dirReady: true, data: val });
            return _usersDirCache;
          }
        } catch (_) { /* справочник не прочитался — ниже старый путь */ }
      }
      const snap = await _db.ref('users').once('value');
      _usersDirCache = snap.val() || {};
      return _usersDirCache;
    } catch (e) { console.warn('users dir load', e); return {}; }
  }

  // ── Одноразовая миграция у Мади: base64-медиа → Storage, наполнение usersPublic ──
  // Ученические клиенты не могут собрать справочник за других, поэтому первый
  // полный проход делает админ (он и так грузит весь users). Идемпотентно:
  // data:-поля конвертируются по одному разу, записи справочника просто обновляются.
  // По завершении ставится флаг shared/config/dirReady — и все клиенты
  // переключаются на тонкий usersPublic.
  let _dirMigrationRan = false;
  async function adminMigrateDirectory() {
    if (_dirMigrationRan) return;
    if (typeof _db === 'undefined' || typeof _storage === 'undefined') return;
    if (!isAdmin()) return;
    _dirMigrationRan = true;
    try {
      // Справочник уже собран (dirReady=true) — полный проход не нужен: новые
      // ученицы наполняют usersPublic сами при входе (pushUserToCloud + зеркала
      // _mirrorPublicField). Без этого гейта Мади скачивала весь users (~1 МБ)
      // через 8 секунд после КАЖДОГО старта приложения.
      if (_dirReadyFlag === null) {
        try { _dirReadyFlag = !!(await _db.ref('shared/config/dirReady').once('value')).val(); } catch (_) {}
      }
      if (_dirReadyFlag) return;
      const snap = await _db.ref('users').once('value');
      const users = snap.val() || {};
      if (!_usersDirCache) { _usersDirCache = users; _adminUsersCache = users; _adminUsersCacheAt = Date.now(); }
      for (const [uid, u] of Object.entries(users)) {
        if (!u || typeof u !== 'object') continue;
        let avatar = u.avatar || null;
        let cover = u.cover || null;
        if (isDataUrl(avatar)) {
          try {
            avatar = await uploadDataUrlToStorage(avatar, `avatars/${uid}.jpg`, CACHE_MUTABLE);
            await _db.ref(`users/${uid}/avatar`).set(avatar);
          } catch (e) { console.warn('avatar migrate', uid, e); avatar = null; }
        }
        if (isDataUrl(cover)) {
          try {
            cover = await uploadDataUrlToStorage(cover, `covers/${uid}.jpg`, CACHE_MUTABLE);
            await _db.ref(`users/${uid}/cover`).set(cover);
          } catch (e) { console.warn('cover migrate', uid, e); cover = null; }
        }
        const entry = {
          name: u.name || null,
          email: u.email || null,
          lastSeen: u.lastSeen || null,
          joinedAt: u.joinedAt || null,
          isAdmin: !!u.isAdmin,
          level: u.level || null,
          gender: u.gender || null,
          bio: u.bio || null,
          avatar: isDataUrl(avatar) ? null : avatar,
          cover: isDataUrl(cover) ? null : cover,
          stats: publicStatsLite(u.stats)
        };
        await _db.ref('usersPublic/' + uid).update(entry);
      }
      await _db.ref('shared/config/dirReady').set(true);
      console.info('usersPublic: справочник собран, dirReady=true');
    } catch (e) {
      console.warn('dir migration', e);
      _dirMigrationRan = false; // не получилось — попробуем в следующей сессии
    }
  }

  // Одноразовая миграция ленты: base64-фото постов (и Мади, и учеников) → Storage.
  // Последние 40 постов сообщества и вся админская лента скачиваются каждым
  // клиентом при каждом запуске — base64 внутри них и был вторым источником
  // взрыва трафика. Идемпотентно: обрабатываются только data:-поля.
  let _feedMediaMigrationRan = false;
  async function adminMigrateFeedMedia() {
    if (_feedMediaMigrationRan) return;
    if (typeof _db === 'undefined' || typeof _storage === 'undefined') return;
    if (!isAdmin()) return;
    _feedMediaMigrationRan = true;
    try {
      // Посты учеников (shared/userFeedPosts): фото поста + аватар автора
      const snap = await _db.ref('shared/userFeedPosts').once('value');
      const posts = snap.val() || {};
      for (const [key, p] of Object.entries(posts)) {
        if (!p) continue;
        if (isDataUrl(p.image)) {
          try {
            const url = await uploadDataUrlToStorage(p.image, `feed/user/${key}.jpg`);
            await _db.ref(`shared/userFeedPosts/${key}/image`).set(url);
          } catch (e) { console.warn('feed image migrate', key, e); }
        }
        if (isDataUrl(p.avatar)) {
          // Свежий URL-аватар автора уже лежит в справочнике после миграции профилей
          const fresh = (p.uid && _usersDirCache && _usersDirCache[p.uid] && _usersDirCache[p.uid].avatar) || null;
          await _db.ref(`shared/userFeedPosts/${key}/avatar`).set(isDataUrl(fresh) ? null : fresh).catch(() => {});
        }
      }
      // Лента Мади (customFeedPosts): узел пишется целиком через Store.set
      const all = Store.get('customFeedPosts', []);
      let changed = false;
      for (const p of all) {
        if (p && isDataUrl(p.image)) {
          try {
            p.image = await uploadDataUrlToStorage(p.image, `feed/admin/${p.id || Date.now()}.jpg`);
            changed = true;
          } catch (e) { console.warn('custom feed migrate', e); }
        }
      }
      if (changed) Store.set('customFeedPosts', all);
      // Комментарии ленты: сотни вшитых base64-аватаров раздули узел до 40+ МБ,
      // и каждый клиент скачивал его ЦЕЛИКОМ при каждом заходе (профайлер 03.07).
      // Меняем base64 на URL-аватар автора из справочника или убираем совсем —
      // рендер и так показывает живой аватар из _userAvatars, поле было fallback'ом.
      const cSnap = await _db.ref('shared/feedComments').once('value');
      const byPost = cSnap.val() || {};
      const fixes = {};
      const urlAvatarOf = uid => {
        const u = (uid && _usersDirCache && _usersDirCache[uid]) || null;
        return (u && u.avatar && !isDataUrl(u.avatar)) ? u.avatar : null;
      };
      Object.entries(byPost).forEach(([pid, comments]) => {
        Object.entries(comments || {}).forEach(([cid, c]) => {
          if (!c || typeof c !== 'object') return;
          if (isDataUrl(c.avatar)) fixes[`${pid}/${cid}/avatar`] = urlAvatarOf(c.uid);
          Object.entries(c.replies || {}).forEach(([rid, r]) => {
            if (r && isDataUrl(r.avatar)) fixes[`${pid}/${cid}/replies/${rid}/avatar`] = urlAvatarOf(r.uid);
          });
        });
      });
      if (Object.keys(fixes).length) {
        await _db.ref('shared/feedComments').update(fixes);
        console.info('feedComments: вычищено base64-аватаров:', Object.keys(fixes).length);
      }
    } catch (e) {
      console.warn('feed media migration', e);
      _feedMediaMigrationRan = false; // доделаем в следующей сессии
    }
  }

  async function searchUsersByName(q) {
    const dir = _usersDirCache || await loadUsersDirectory();
    const me = myUid();
    const qq = (q || '').toLowerCase().trim();
    return Object.entries(dir)
      .map(([uid, u]) => ({ uid, ...u }))
      .filter(u => u.uid !== me)
      .filter(u => !qq || (u.name || '').toLowerCase().includes(qq) || (u.email || '').toLowerCase().includes(qq))
      .sort((a, b) => (b.lastSeen || 0) - (a.lastSeen || 0))
      .slice(0, 40);
  }

  async function sendFriendRequest(toUid, toName) {
    if (typeof _db === 'undefined') { toast(t('ui.067')); return; }
    const me = myUid();
    if (!me || me === 'guest') { toast(t('ui.068')); return; }
    if (me === toUid) { toast(t('ui.069')); return; }
    if (_sendingFriendReq.has(toUid)) return;       // Уже отправляем — игнор спама
    if (_outgoingCache[toUid])        { toast(t('ui.070')); return; }
    if (_friendsCache[toUid])         { toast(t('ui.071')); return; }
    _sendingFriendReq.add(toUid);
    if (document.getElementById('add-friend-modal')) filterAddFriend();
    try {
      const existingFr = await _db.ref(`users/${me}/friends/${toUid}`).once('value');
      if (existingFr.exists()) { toast(t('ui.071')); return; }
      const existingOut = await _db.ref(`users/${me}/outgoing/${toUid}`).once('value');
      if (existingOut.exists()) { toast(t('ui.070')); return; }
      const ref = _db.ref(`users/${toUid}/inbox`).push();
      const updates = {};
      updates[`users/${toUid}/inbox/${ref.key}`] = {
        type: 'friend_request',
        from: me,
        fromName: myName(),
        at: Date.now()
      };
      updates[`users/${me}/outgoing/${toUid}`] = {
        name: toName || '',
        at: Date.now(),
        inboxKey: ref.key
      };
      await _db.ref().update(updates);
      toast(t('social.reqSent'), 'var(--sage)');
    } catch (e) {
      console.warn('sendFriendRequest failed:', e);
      toast(t('ui.072') + (e.code || e.message || t('ui.072')));
    } finally {
      _sendingFriendReq.delete(toUid);
      if (document.getElementById('add-friend-modal')) filterAddFriend();
    }
  }

  async function cancelFriendRequest(toUid) {
    const me = myUid();
    if (typeof _db === 'undefined') return;
    const outRef = _db.ref(`users/${me}/outgoing/${toUid}`);
    const snap = await outRef.once('value');
    const data = snap.val();
    const updates = {};
    updates[`users/${me}/outgoing/${toUid}`] = null;
    if (data && data.inboxKey) {
      updates[`users/${toUid}/inbox/${data.inboxKey}`] = null;
    }
    try {
      await _db.ref().update(updates);
      toast(t('ui.073'));
      if (document.getElementById('add-friend-modal')) filterAddFriend();
    } catch (e) { console.warn(e); toast(t('ui.074')); }
  }

  async function acceptFriendRequest(reqKey, fromUid, fromName) {
    const me = myUid();
    const now = Date.now();
    const updates = {};
    updates[`users/${me}/friends/${fromUid}`] = { name: fromName, since: now };
    updates[`users/${fromUid}/friends/${me}`] = { name: myName(), since: now };
    updates[`users/${me}/inbox/${reqKey}`] = null;
    // Clean up the sender's outgoing record now that we're friends
    updates[`users/${fromUid}/outgoing/${me}`] = null;
    try {
      await _db.ref().update(updates);
      toast(t('social.nowFriends'), 'var(--sage)');
    } catch (e) { console.warn(e); toast(t('ui.075')); }
  }

  async function declineFriendRequest(reqKey, fromUid) {
    const me = myUid();
    const updates = {};
    updates[`users/${me}/inbox/${reqKey}`] = null;
    if (fromUid) updates[`users/${fromUid}/outgoing/${me}`] = null;
    try { await _db.ref().update(updates); } catch (_) {}
  }

  async function removeFriend(friendUid) {
    if (!confirm(t('ui.076'))) return;
    const me = myUid();
    const updates = {};
    updates[`users/${me}/friends/${friendUid}`] = null;
    updates[`users/${friendUid}/friends/${me}`] = null;
    // Счётчики непрочитанного — с обеих сторон: без чата в списке их нечем
    // обнулить, и цифра на вкладке «Общение» зависала бы навсегда.
    updates[`users/${me}/unreadFrom/${friendUid}`] = null;
    updates[`users/${friendUid}/unreadFrom/${me}`] = null;
    try {
      await _db.ref().update(updates);
      toast(t('ui.077'));
    } catch (e) { console.warn(e); }
  }

  async function sendChatMessage(otherUid, otherName, text, replyTo) {
    text = (text || '').trim();
    if (!text) return;
    if (text.length > 2000) text = text.slice(0, 2000);
    if (typeof _db === 'undefined') throw new Error('Нет связи с сервером');
    const me = myUid();
    if (!me || me === 'guest') throw new Error('Войди в аккаунт');
    const chatId = chatIdFor(me, otherUid);
    const now = Date.now();
    const updates = {};
    const newRef = _db.ref(`chats/${chatId}/messages`).push();
    const msg = { from: me, fromName: myName(), text, at: now };
    if (replyTo && replyTo.id) {
      msg.replyTo = {
        id: replyTo.id,
        text: String(replyTo.text || '').slice(0, 200),
        from: replyTo.from || '',
        fromName: replyTo.fromName || ''
      };
    }
    updates[`chats/${chatId}/messages/${newRef.key}`] = msg;
    updates[`chats/${chatId}/meta/members/${me}`] = true;
    updates[`chats/${chatId}/meta/members/${otherUid}`] = true;
    updates[`chats/${chatId}/meta/lastMessage`] = text.slice(0, 140);
    updates[`chats/${chatId}/meta/lastAt`] = now;
    updates[`chats/${chatId}/meta/lastFrom`] = me;
    updates[`chats/${chatId}/meta/lastFromName`] = myName();
    // My own read pointer moves forward (I just wrote, so I've seen up to now).
    updates[`chats/${chatId}/meta/read/${me}`] = now;
    // Bump the unread COUNTER on the other side (Telegram-style number, not just a dot).
    updates[`users/${otherUid}/unreadFrom/${me}`] = firebase.database.ServerValue.increment(1);
    // Auto-friend on first contact (covers admin→student first message).
    // No-op idempotent overwrite if already friends.
    if (!_friendsCache || !_friendsCache[otherUid]) {
      updates[`users/${me}/friends/${otherUid}`]   = { name: otherName || '', since: now };
      updates[`users/${otherUid}/friends/${me}`]   = { name: myName(),       since: now };
      // Clear any pending request leftovers between these two users
      updates[`users/${me}/outgoing/${otherUid}`]  = null;
      updates[`users/${otherUid}/outgoing/${me}`]  = null;
    }
    await _db.ref().update(updates);
    bumpChatActivity(otherUid, now); // my outgoing message also surfaces the chat
  }

  // ── Group chat: send a message to chats/<gid> and bump unread for every member ──
  async function sendGroupMessage(gid, text, replyTo) {
    text = (text || '').trim();
    if (!text) return;
    if (text.length > 2000) text = text.slice(0, 2000);
    if (typeof _db === 'undefined') throw new Error('Нет связи с сервером');
    const me = myUid();
    if (!me || me === 'guest') throw new Error('Войди в аккаунт');
    const now = Date.now();
    const updates = {};
    const newRef = _db.ref(`chats/${gid}/messages`).push();
    const msg = { from: me, fromName: myName(), text, at: now };
    if (replyTo && replyTo.id) {
      msg.replyTo = {
        id: replyTo.id,
        text: String(replyTo.text || '').slice(0, 200),
        from: replyTo.from || '',
        fromName: replyTo.fromName || ''
      };
    }
    updates[`chats/${gid}/messages/${newRef.key}`] = msg;
    updates[`chats/${gid}/meta/lastMessage`] = text.slice(0, 140);
    updates[`chats/${gid}/meta/lastAt`] = now;
    updates[`chats/${gid}/meta/lastFrom`] = me;
    updates[`chats/${gid}/meta/lastFromName`] = myName();
    updates[`chats/${gid}/meta/read/${me}`] = now;
    // Unread counter for every member except me (key = gid, just like DM keys by uid).
    // Чат сообщества — исключение: он может быть очень большим, веерные записи
    // unread по всем участникам не делаем; «новое» считается локально (communityReadAt).
    let members = (gid === COMMUNITY_GID) ? [] : Object.keys(_chatMembers || {});
    if (!members.length && gid !== COMMUNITY_GID) {
      // члены ещё не подгрузились (медленная сеть) — дочитываем напрямую
      try {
        const snap = await _db.ref(`chats/${gid}/meta/members`).once('value');
        members = Object.keys(snap.val() || {});
      } catch (_) {}
    }
    members.forEach(uid => {
      if (uid !== me) updates[`users/${uid}/unreadFrom/${gid}`] = firebase.database.ServerValue.increment(1);
    });
    await _db.ref().update(updates);
    bumpChatActivity(gid, now);
  }

  // ── Group chat: creation ──
  function openCreateGroupModal() {
    if (!isLoggedInForChat()) { toast(t('grp.loginNeeded')); return; }
    // Admin invites any student; a student invites their friends.
    let friends;
    if (isAdmin()) {
      const dir = _usersDirCache || {};
      const me = myUid();
      friends = {};
      Object.keys(dir).forEach(uid => {
        if (uid !== me && !(dir[uid] && dir[uid].isAdmin)) friends[uid] = { name: dir[uid].name || t('grp.defStudent') };
      });
    } else {
      friends = _friendsCache || {};
    }
    const fids = Object.keys(friends);
    if (!fids.length) { toast(isAdmin() ? t('grp.noStudents') : t('grp.noFriends')); return; }
    _groupPhoto = null;
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'create-group-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:380px;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px;">
          <div>
            <div class="page-eyebrow">${t('grp.eyebrow')}</div>
            <div class="display" style="font-size:20px;color:var(--berry);margin-top:2px;">${t('grp.title')}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px;color:var(--soft);cursor:pointer;line-height:1;padding:2px 6px;">×</div>
        </div>
        <div style="display:flex;align-items:center;gap:13px;margin-bottom:12px;">
          <button type="button" id="group-photo-btn" onclick="document.getElementById('group-photo-file').click()" class="group-photo-pick" aria-label="${escAttr(t('grp.photoAria'))}">
            <i class="fa-solid fa-camera"></i>
          </button>
          <input type="file" accept="image/*" id="group-photo-file" style="display:none;" onchange="onGroupPhotoPick(event)">
          <div style="flex:1;min-width:0;">
            <input id="group-title-input" class="input" placeholder="${escAttr(t('grp.namePh'))}" maxlength="60" style="font-size:14px;">
          </div>
        </div>
        <textarea id="group-desc-input" class="input" rows="2" placeholder="${escAttr(t('grp.descPh'))}" maxlength="200" style="font-size:13px;resize:vertical;margin-bottom:4px;"></textarea>
        <div style="font-size:10px;letter-spacing:.18em;color:var(--soft);margin:14px 2px 8px;">${t('grp.members')}</div>
        <div id="group-member-list" style="display:grid;gap:6px;max-height:260px;overflow-y:auto;">
          ${fids.map(uid => {
            const nm = (friends[uid] && friends[uid].name) || t('grp.defFriend');
            const dir = (_usersDirCache && _usersDirCache[uid]) || {};
            const av = dir.avatar
              ? `<div class="chat-row-av" style="width:34px;height:34px;background:url(${dir.avatar}) center/cover no-repeat;"></div>`
              : `<div class="chat-row-av chat-row-av-initial" style="width:34px;height:34px;font-size:13px;">${escHtml(nm.charAt(0).toUpperCase())}</div>`;
            return `
              <label class="group-pick-row">
                ${av}
                <span style="flex:1;font-size:13px;font-weight:600;color:var(--berry);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(nm)}</span>
                <input type="checkbox" class="group-pick-check" value="${escHtml(uid)}">
                <span class="group-pick-mark"><i class="fa-solid fa-check"></i></span>
              </label>`;
          }).join('')}
        </div>
        <button onclick="createGroupChat()" class="btn btn-primary btn-block" style="margin-top:16px;"><i class="fa-solid fa-user-group" style="font-size:11px;"></i> ${t('grp.create')}</button>
      </div>`;
    document.body.appendChild(m);
    setTimeout(() => { document.getElementById('group-title-input')?.focus(); }, 80);
  }

  let _groupPhoto = null; // временный dataURL фото при создании группы
  async function onGroupPhotoPick(ev) {
    const file = ev.target.files && ev.target.files[0];
    if (!file) return;
    try {
      _groupPhoto = await compressImageFile(file, 256, 0.8);
      const btn = document.getElementById('group-photo-btn');
      if (btn) { btn.style.background = `url(${_groupPhoto}) center/cover no-repeat`; btn.innerHTML = ''; }
    } catch (_) { toast(t('grp.photoFail')); }
  }
  async function createGroupChat() {
    const titleInp = document.getElementById('group-title-input');
    const title = ((titleInp && titleInp.value) || '').trim();
    const desc = (document.getElementById('group-desc-input')?.value || '').trim();
    const picked = [...document.querySelectorAll('#group-member-list .group-pick-check:checked')].map(c => c.value);
    if (!title) { toast(t('grp.needName')); titleInp?.focus(); return; }
    if (!picked.length) { toast(t('grp.needMember')); return; }
    if (typeof _db === 'undefined') { toast(t('grp.noConn')); return; }
    const me = myUid();
    const now = Date.now();
    const gid = 'g_' + _db.ref('chats').push().key;
    const members = { [me]: true };
    picked.forEach(uid => { members[uid] = true; });
    // Фото группы — в Storage: meta чата читается всеми участниками при каждой
    // отрисовке списка, base64 внутри неё умножается на каждое открытие.
    let groupPhoto = _groupPhoto || null;
    if (isDataUrl(groupPhoto) && typeof _storage !== 'undefined') {
      try { groupPhoto = await uploadDataUrlToStorage(groupPhoto, `groups/${gid}.jpg`); } catch (_) {}
    }
    const updates = {};
    updates[`chats/${gid}/meta`] = {
      group: true, title, desc: desc || null, photo: groupPhoto,
      members, owner: me, createdAt: now,
      lastMessage: '', lastAt: now, lastFrom: '', lastFromName: '',
      read: { [me]: now }
    };
    Object.keys(members).forEach(uid => {
      updates[`users/${uid}/groups/${gid}`] = { title, since: now };
    });
    // Системное сообщение о создании + участниках
    const sysKey = _db.ref(`chats/${gid}/messages`).push().key;
    updates[`chats/${gid}/messages/${sysKey}`] = { type: 'system', text: t('ui.r030',{name: myName(), title: title}), at: now };
    try {
      await _db.ref().update(updates);
      _groupPhoto = null;
      document.getElementById('create-group-modal')?.remove();
      toast(t('ui.078',{title: title}), 'var(--sage)');
      openGroupChat(gid, title);
    } catch (e) { console.warn(e); toast(t('ui.079')); }
  }

  // ── Typing indicator (Telegram-style "печатает…") ──
  function signalTyping() {
    const me = myUid(); const chatId = _chatCurrentId;
    if (!me || me === 'guest' || !chatId || typeof _db === 'undefined') return;
    const now = Date.now();
    if (now - _typingWriteAt > 2200) {           // throttle writes
      _typingWriteAt = now;
      try { _db.ref(`chats/${chatId}/meta/typing/${me}`).set(now); } catch (_) {}
    }
    if (_typingClearTimer) clearTimeout(_typingClearTimer);
    _typingClearTimer = setTimeout(stopTyping, 3500); // auto-clear after a pause
  }
  function stopTyping() {
    if (_typingClearTimer) { clearTimeout(_typingClearTimer); _typingClearTimer = null; }
    _typingWriteAt = 0;
    const me = myUid(); const chatId = _chatCurrentId;
    if (!me || me === 'guest' || !chatId || typeof _db === 'undefined') return;
    try { _db.ref(`chats/${chatId}/meta/typing/${me}`).remove(); } catch (_) {}
  }

  // ── Emoji picker for the chat input ──
  const CHAT_EMOJIS = ['😀','😂','🥹','😊','😍','😘','🥰','😎','🤗','😅','😴','😭','😱','🥳','😡','👍','👎','👏','🙏','💪','🔥','✨','🎉','💯','❤️','🧡','💛','💚','💙','💜','🤍','💔','🌸','🌺','🌷','🌼','🐰','🐻','🐱','🍓','🍡','☕','🎮','📚','✅','💖'];
  function closeEmojiPanel() {
    const panel = document.getElementById('chat-emoji-panel');
    const btn = document.getElementById('chat-emoji-btn');
    if (panel) panel.style.display = 'none';
    if (btn) btn.classList.remove('active');
  }
  function toggleEmojiPicker() {
    const panel = document.getElementById('chat-emoji-panel');
    const btn = document.getElementById('chat-emoji-btn');
    if (!panel) return;
    if (panel.style.display !== 'none') { closeEmojiPanel(); return; }
    if (!panel.dataset.filled) {
      panel.innerHTML = CHAT_EMOJIS.map(e => `<button type="button" class="emoji-cell" onclick="insertEmoji('${e}')">${e}</button>`).join('');
      panel.dataset.filled = '1';
    }
    panel.style.display = 'flex';
    if (btn) btn.classList.add('active');
  }
  function insertEmoji(em) {
    const inp = document.getElementById('chat-input');
    if (!inp) return;
    const start = inp.selectionStart != null ? inp.selectionStart : inp.value.length;
    const end = inp.selectionEnd != null ? inp.selectionEnd : inp.value.length;
    inp.value = inp.value.slice(0, start) + em + inp.value.slice(end);
    const caret = start + em.length;
    inp.focus();
    try { inp.setSelectionRange(caret, caret); } catch (_) {}
    signalTyping();
  }

  async function markChatRead(key, chatId) {
    // key = friend uid (DM) or gid (group); chatId defaults to the DM id for the uid.
    const me = myUid();
    if (!me || me === 'guest' || typeof _db === 'undefined') return;
    if (!chatId) chatId = chatIdFor(me, key);
    try {
      const updates = {};
      updates[`users/${me}/unreadFrom/${key}`] = null;            // clear my unread counter
      updates[`chats/${chatId}/meta/read/${me}`] = Date.now();    // tell the sender I've read up to now (✓✓)
      await _db.ref().update(updates);
    } catch (_) {}
  }
  // Normalize an unread value to a small count. Legacy entries stored a timestamp
  // (~1.7e12); treat those as a single unread so old data doesn't show "9+".
  function unreadCountFor(uid) {
    const v = Number(_unreadFromCache && _unreadFromCache[uid]) || 0;
    if (v <= 0) return 0;
    return v > 100000 ? 1 : v;
  }

  let _unreadFromCache = {};
  // ── Chat list metadata: last message preview + server-side ordering ──
  // key = friend uid (DM) or group id; value = {lastMessage, lastAt, lastFrom, lastFromName}
  let _chatMetaCache = {};
  async function loadChatMetas(items) {
    if (typeof _db === 'undefined') return;
    await Promise.all(items.map(async it => {
      try {
        const snap = await _db.ref(`chats/${it.chatId}/meta`).once('value');
        const meta = snap.val() || {};
        _chatMetaCache[it.key] = {
          lastMessage: meta.lastMessage || '',
          lastAt: meta.lastAt || 0,
          lastFrom: meta.lastFrom || '',
          lastFromName: meta.lastFromName || '',
          members: meta.members || null,
          title: meta.title || '',
          photo: meta.photo || '',
          desc: meta.desc || ''
        };
      } catch (_) {}
    }));
  }
  // Telegram-style time label in the chat list: HH:MM today, weekday this week, DD.MM later.
  function chatListTimeLabel(ts) {
    if (!ts) return '';
    const d = new Date(ts), now = new Date();
    const sameDay = d.toDateString() === now.toDateString();
    if (sameDay) return `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    const diffDays = (now - d) / 86400000;
    if (diffDays < 7) return ['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d.getDay()];
    return `${String(d.getDate()).padStart(2,'0')}.${String(d.getMonth()+1).padStart(2,'0')}`;
  }
  // Deterministic per-user color index (0–6) for sender names in group chats.
  function nameColorIdx(uid) {
    let h = 0;
    const s = String(uid || '');
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h % 7;
  }
  // Chat list ordering + new-message popups
  let _chatLastAt = {};          // uid -> last activity ts (local, persisted per user)
  let _chatLastAtLoaded = false;
  let _prevUnreadFrom = null;    // diff source: detect a NEW incoming message
  function loadChatLastAt() {
    try { _chatLastAt = UStore.get('chatLastAt', {}) || {}; } catch (_) { _chatLastAt = {}; }
    _chatLastAtLoaded = true;
  }
  function bumpChatActivity(uid, ts) {
    if (!uid) return;
    if (!_chatLastAtLoaded) loadChatLastAt();
    _chatLastAt[uid] = ts || Date.now();
    try { UStore.set('chatLastAt', _chatLastAt); } catch (_) {}
  }
  // ── Закреп чатов (локально, как chatLastAt) ──
  let _pinnedChats = null;
  function _loadPins() { if (_pinnedChats === null) { try { _pinnedChats = UStore.get('pinnedChats', {}) || {}; } catch (_) { _pinnedChats = {}; } } return _pinnedChats; }
  function isChatPinned(key) { return !!_loadPins()[key]; }
  function toggleChatPin(key) {
    const p = _loadPins();
    if (p[key]) delete p[key]; else p[key] = Date.now();
    try { UStore.set('pinnedChats', p); } catch (_) {}
    if (isAdmin()) renderAdminChatList(); else renderFriendsAndChat();
  }
  // Called when users/{me}/unreadFrom changes — bumps recency + pops a banner for new ones.
  function handleUnreadFromUpdate(val) {
    val = val || {};
    if (_prevUnreadFrom) {
      Object.keys(val).forEach(uid => {
        const nv = Number(val[uid]) || 0, ov = Number(_prevUnreadFrom[uid]) || 0;
        if (nv > ov) {                       // a new message arrived from `uid`
          bumpChatActivity(uid);
          if (uid !== _chatOtherUid) notifyNewMessage(uid); // skip if that chat is open
        }
      });
    }
    _prevUnreadFrom = val;
    _unreadFromCache = val;
    renderFriendsAndChat();
    updateChatBadges();
    scheduleUnreadCleanup();
  }
  function notifyNewMessage(key) {
    // key = friend uid (DM) or gid (group chat)
    const isGroup = !!(_groupsCache && _groupsCache[key]);
    const dir = (_usersDirCache && _usersDirCache[key]) || {};
    const fr  = (_friendsCache && _friendsCache[key]) || {};
    const name = isGroup
      ? (_groupsCache[key].title || t('grp.defTitle'))
      : (dir.name || fr.name || t('chat.newMsg'));
    showChatPopup(key, name, isGroup ? '' : (dir.avatar || ''), '', isGroup);
    // Enrich with the actual last message text once it's available.
    if (typeof _db !== 'undefined') {
      try {
        const chatId = isGroup ? key : chatIdFor(myUid(), key);
        _db.ref(`chats/${chatId}/meta/lastMessage`).once('value')
          .then(s => { const t = s.val(); if (t) updateChatPopupText(key, t); }).catch(() => {});
      } catch (_) {}
    }
  }
  function _popupId(uid) { return 'chat-popup-' + String(uid).replace(/[^a-zA-Z0-9_-]/g, '_'); }
  function showChatPopup(uid, name, avatar, text, isGroup) {
    document.getElementById(_popupId(uid))?.remove();
    const el = document.createElement('div');
    el.className = 'chat-popup';
    el.id = _popupId(uid);
    el.setAttribute('role', 'button');
    el.onclick = () => {
      el.remove();
      try { switchScreen('social'); } catch (_) {}
      if (isGroup) openGroupChat(uid, name); else openChat(uid, name);
    };
    const av = avatar
      ? `<div class="chat-popup-av" style="background:url(${avatar}) center/cover no-repeat;"></div>`
      : `<div class="chat-popup-av">${isGroup ? '<i class="fa-solid fa-user-group" style="font-size:13px;"></i>' : escHtml((name || '?').charAt(0).toUpperCase())}</div>`;
    el.innerHTML = `${av}
      <div class="chat-popup-body">
        <div class="chat-popup-name">${escHtml(name)}</div>
        <div class="chat-popup-text" id="${_popupId(uid)}-t">${text ? escHtml(text.length > 64 ? text.slice(0, 64) + '…' : text) : 'новое сообщение 💬'}</div>
      </div>
      <i class="fa-solid fa-chevron-right" style="color:var(--soft);font-size:12px;flex-shrink:0;"></i>`;
    document.body.appendChild(el);
    requestAnimationFrame(() => el.classList.add('in'));
    el._t = setTimeout(() => { el.classList.remove('in'); el.classList.add('out'); setTimeout(() => el.remove(), 320); }, 4400);
  }
  function updateChatPopupText(uid, text) {
    const t = document.getElementById(_popupId(uid) + '-t');
    if (t && text) t.textContent = text.length > 64 ? text.slice(0, 64) + '…' : text;
  }
  let _friendsListenerOffs = [];
  // Пришли ли первые снапшоты friends/groups — до этого нельзя судить,
  // осиротел ли ключ в unreadFrom (пустой кэш ≠ «друзей нет»).
  let _friendsLoaded = false, _groupsLoaded = false;
  let _unreadCleanupTimer = null;
  function detachFriendsListeners() {
    _friendsListenerOffs.forEach(off => { try { off(); } catch(_){} });
    _friendsListenerOffs = [];
    _friendsLoaded = false; _groupsLoaded = false;
    if (_unreadCleanupTimer) { clearTimeout(_unreadCleanupTimer); _unreadCleanupTimer = null; }
  }

  function attachFriendsListeners() {
    detachFriendsListeners();
    if (typeof _db === 'undefined') return;
    const me = myUid();
    if (!me || me === 'guest') return;
    const wire = (path, onSnap) => {
      const ref = _db.ref(path);
      const handler = snap => onSnap(snap.val() || {});
      ref.on('value', handler);
      _friendsListenerOffs.push(() => ref.off('value', handler));
    };
    wire(`users/${me}/friends`,  val => { _friendsCache  = val; _friendsLoaded = true; renderFriendsAndChat(); updateChatBadges(); scheduleUnreadCleanup(); if (document.getElementById('add-friend-modal')) filterAddFriend(); });
    wire(`users/${me}/groups`,   val => { _groupsCache   = val; _groupsLoaded = true; renderFriendsAndChat(); updateChatBadges(); scheduleUnreadCleanup(); });
    wire(`users/${me}/inbox`,    val => { _inboxCache    = val; if (isAdmin()) adminAutoAcceptRequests(val); renderFriendsAndChat(); updateChatBadges(); processReferralRewards(); });
    wire(`users/${me}/outgoing`, val => { _outgoingCache = val; if (document.getElementById('add-friend-modal')) filterAddFriend(); });
    wire(`users/${me}/unreadFrom`, val => { handleUnreadFromUpdate(val); });
    // Живой лёгкий слушатель сообщества: только meta/lastAt (одно число, НЕ members и
    // НЕ сообщения — трафик минимален). При новом сообщении дочитываем lastFrom и
    // обновляем бейдж вкладки «Общение», чтобы «новое» было видно, не заходя в чат.
    const commLaRef = _db.ref(`chats/${COMMUNITY_GID}/meta/lastAt`);
    const commLaH = async snap => {
      const lastAt = Number(snap.val()) || 0;
      let lastFrom = '';
      try { lastFrom = (await _db.ref(`chats/${COMMUNITY_GID}/meta/lastFrom`).once('value')).val() || ''; } catch (_) {}
      _chatMetaCache[COMMUNITY_GID] = Object.assign({}, _chatMetaCache[COMMUNITY_GID] || {}, { lastAt, lastFrom });
      updateChatBadges();
      if (document.getElementById('screen-social')?.classList.contains('active')) renderFriendsAndChat();
    };
    commLaRef.on('value', commLaH);
    _friendsListenerOffs.push(() => commLaRef.off('value', commLaH));
  }

  // Ключ из unreadFrom «виден» в списке чатов: сообщество, моя группа, друг,
  // а у админа — любая ученица из каталога (его список чатов = все ученицы;
  // пока каталог не загружен, админу считаем все ключи, как раньше).
  // ВАЖНО: у админа список чатов исключает ДРУГИХ админов (renderAdminChatList),
  // поэтому личка админ↔админ невидима и некликабельна — её непрочитанное НЕ
  // считаем «видимым», иначе бейдж «Общение» рос бы фантомом, а обнулить негде.
  function _isVisibleChatKey(key) {
    if (key === COMMUNITY_GID) return true;
    if (_groupsCache && _groupsCache[key]) return true;
    if (isAdmin()) {
      if (!_usersDirCache) return true;                 // каталог ещё не загружен — как раньше
      return !!(_usersDirCache[key] && !_usersDirCache[key].isAdmin);
    }
    if (_friendsCache && _friendsCache[key]) return true;
    return false;
  }
  // Админ не имеет UI для заявок в друзья (его список чатов = весь каталог учениц,
  // а первый DM и так авто-дружит), поэтому входящие friend_request к админу
  // принимаются молча и автоматически. Это (1) чистит счётчик, который иначе рос бы
  // вечно — принять/отклонить заявку админу негде; (2) снимает у ученицы зависший
  // статус «Заявка отправлена» и сразу делает её другом Мади (чтобы могла писать).
  let _adminAcceptingReqs = false;
  function adminAutoAcceptRequests(inbox) {
    if (!isAdmin() || typeof _db === 'undefined' || _adminAcceptingReqs) return;
    const me = myUid();
    if (!me || me === 'guest') return;
    const reqs = Object.entries(inbox || {}).filter(([, v]) => v && v.type === 'friend_request');
    if (!reqs.length) return;
    _adminAcceptingReqs = true;
    const now = Date.now();
    const updates = {};
    reqs.forEach(([reqKey, r]) => {
      const fromUid = r.from;
      if (fromUid) {
        updates[`users/${me}/friends/${fromUid}`] = { name: r.fromName || '', since: now };
        updates[`users/${fromUid}/friends/${me}`] = { name: myName(), since: now };
        updates[`users/${fromUid}/outgoing/${me}`] = null; // снять «Заявка отправлена» у ученицы
      }
      updates[`users/${me}/inbox/${reqKey}`] = null;        // убрать заявку из инбокса админа
    });
    _db.ref().update(updates).then(() => {}, () => {}).then(() => { _adminAcceptingReqs = false; });
  }
  // Осиротевшие счётчики (дружбу удалили — чата в списке нет, открыть и
  // «прочитать» его нельзя) подчищаем из БД, иначе они копятся навсегда.
  // Дебаунс: дружба и счётчик пишутся одним атомарным update, но события
  // разных слушателей приходят порознь — даём кэшам устаканиться.
  function scheduleUnreadCleanup() {
    if (_unreadCleanupTimer) clearTimeout(_unreadCleanupTimer);
    _unreadCleanupTimer = setTimeout(() => {
      _unreadCleanupTimer = null;
      if (!_friendsLoaded || !_groupsLoaded) return;
      if (isAdmin() && !_usersDirCache) return; // без каталога ученицу от сироты не отличить
      const me = myUid();
      if (!me || me === 'guest' || typeof _db === 'undefined') return;
      const orphans = Object.keys(_unreadFromCache || {}).filter(k => !_isVisibleChatKey(k));
      if (!orphans.length) return;
      const updates = {};
      orphans.forEach(k => { updates[`users/${me}/unreadFrom/${k}`] = null; });
      _db.ref().update(updates).catch(() => {});
    }, 4000);
  }

  function updateChatBadges() {
    // Friend requests + unread messages → badge on the "Общение" tab.
    // Update BOTH nav copies (mobile bottom nav + desktop sidebar), since only
    // one is visible at a time depending on viewport.
    // Считаем только то, что реально видно на экране «Общение»: заявки в друзья
    // (в inbox бывают и другие типы писем — например referral) и непрочитанное
    // из чатов, которые есть в списке. Иначе бейдж показывает фантомную цифру.
    // У АДМИНА заявок в друзья на экране нет (renderAdminChatList их не рисует, а
    // входящие авто-принимаются) — не считаем их, иначе бейдж рос бы вечно.
    const requestsCount = isAdmin()
      ? 0
      : Object.values(_inboxCache || {}).filter(v => v && v.type === 'friend_request').length;
    const unreadCount = Object.keys(_unreadFromCache || {})
      .filter(_isVisibleChatKey)
      .reduce((a, uid) => a + unreadCountFor(uid), 0);
    // Сообщество не ведёт веерный unread-счётчик (чат большой) — добавляем его как
    // единицу «есть новое», иначе на вкладке «Общение» не видно новых сообщений
    // сообщества, пока туда не зайдёшь (отзыв 09.07).
    const total = requestsCount + unreadCount + (_communityHasNew() ? 1 : 0);
    document.querySelectorAll('.nav-item[data-screen="social"]').forEach(navItem => {
      let badge = navItem.querySelector('.profile-nav-badge');
      if (total > 0) {
        if (!badge) {
          badge = document.createElement('span');
          badge.className = 'profile-nav-badge';
          navItem.appendChild(badge);
        }
        badge.textContent = total > 9 ? '9+' : String(total);
      } else if (badge) {
        badge.remove();
      }
    });
  }

  function friendRowHtml(uid, info) {
    const rawName = (info && info.name) ? info.name : 'Друг';
    const name = escHtml(rawName);
    const unread = unreadCountFor(uid);
    const dir = (_usersDirCache && _usersDirCache[uid]) || {};
    const isAdmin = dir.isAdmin;
    const online = dir.lastSeen && (Date.now() - dir.lastSeen) < ONLINE_WINDOW_MS;
    const meta = _chatMetaCache[uid] || {};
    const avatarInner = dir.avatar
      ? `<div class="photo-zoom chat-row-av" style="background:url(${dir.avatar}) center/cover no-repeat;"></div>`
      : `<div class="chat-row-av chat-row-av-initial">${escHtml(name.charAt(0).toUpperCase())}</div>`;
    const avatar = `<div class="friend-avatar-wrap">${avatarInner}${online ? `<span class="friend-online-dot" title="${t('chat.online')}"></span>` : ''}</div>`;
    // Telegram-style preview: "Ты: …" for my own last message, plain text otherwise.
    let preview;
    if (meta.lastMessage) {
      const mine = meta.lastFrom === myUid();
      preview = `${mine ? `<span class="chat-row-me">${t('chat.you')}</span> ` : ''}${escHtml(meta.lastMessage)}`;
    } else {
      preview = online ? `<span style="color:var(--ok-ink);font-weight:600;">${t('chat.online')}</span>` : t('chat.firstMsg');
    }
    const timeLabel = chatListTimeLabel(meta.lastAt);
    const pinned = isChatPinned(uid);
    return `
      <div class="card card-press chat-list-row${pinned ? ' chat-pinned' : ''}" data-chat-name="${escAttr(rawName.toLowerCase())}" onclick="openChat('${escHtml(uid)}','${name.replace(/'/g,"&#39;")}')">
        ${avatar}
        <div class="chat-row-main">
          <div class="chat-row-top">
            <span class="chat-row-name">${pinned ? '<i class="fa-solid fa-thumbtack chat-pin-i"></i> ' : ''}${name}${isAdmin ? ' <span class="chip chip-coral" style="font-size:9px;padding:1px 6px;">' + t('ui.080') + '</span>' : ''}${dir.sonbae ? ' <span class="chip chip-gold" style="font-size:9px;padding:1px 6px;" title="선배">🎓</span>' : ''}</span>
            <span class="chat-row-time ${unread > 0 ? 'unread' : ''}">${timeLabel}</span>
          </div>
          <div class="chat-row-bottom">
            <span class="chat-row-preview">${preview}</span>
            ${unread > 0 ? `<span class="chat-unread-badge">${unread > 99 ? '99+' : unread}</span>` : ''}
            <button class="chat-pin-btn" onclick="event.stopPropagation(); toggleChatPin('${escHtml(uid)}')" aria-label="${pinned ? t('chat.unpin') : t('chat.pin')}" title="${pinned ? t('chat.unpin') : t('chat.pin')}"><i class="fa-solid fa-thumbtack"></i></button>
          </div>
        </div>
      </div>`;
  }

  function groupRowHtml(gid, info) {
    const rawTitle = (info && info.title) || (_chatMetaCache[gid] && _chatMetaCache[gid].title) || t('grp.defTitle');
    const title = escHtml(rawTitle);
    const unread = unreadCountFor(gid);
    const meta = _chatMetaCache[gid] || {};
    const memberCount = meta.members ? Object.keys(meta.members).length : 0;
    let preview;
    if (meta.lastMessage) {
      const mine = meta.lastFrom === myUid();
      const who = mine ? '<span class="chat-row-me">' + t('ui.081') + '</span>' : (meta.lastFromName ? `<span class="chat-row-me">${escHtml(meta.lastFromName)}:</span>` : '');
      preview = `${who} ${escHtml(meta.lastMessage)}`;
    } else {
      preview = memberCount ? t('ui.r032',{n: memberCount}) : t('ui.r031');
    }
    const timeLabel = chatListTimeLabel(meta.lastAt);
    const photo = meta.photo || (info && info.photo);
    const avInner = photo
      ? `<div class="chat-row-av" style="background:url(${photo}) center/cover no-repeat;"></div>`
      : `<div class="chat-row-av chat-group-av"><i class="fa-solid fa-user-group"></i></div>`;
    const pinned = isChatPinned(gid);
    return `
      <div class="card card-press chat-list-row${pinned ? ' chat-pinned' : ''}" data-chat-name="${escAttr(rawTitle.toLowerCase())}" onclick="openGroupChat('${escHtml(gid)}','${title.replace(/'/g,"&#39;")}')">
        <div class="chat-av-wrap">${avInner}<span class="chat-group-tag" title="${t('ui.082')}"><i class="fa-solid fa-user-group"></i></span></div>
        <div class="chat-row-main">
          <div class="chat-row-top">
            <span class="chat-row-name">${pinned ? '<i class="fa-solid fa-thumbtack chat-pin-i"></i> ' : ''}${title}</span>
            <span class="chat-row-time ${unread > 0 ? 'unread' : ''}">${timeLabel}</span>
          </div>
          <div class="chat-row-bottom">
            <span class="chat-row-preview">${preview}</span>
            ${unread > 0 ? `<span class="chat-unread-badge">${unread > 99 ? '99+' : unread}</span>` : ''}
            <button class="chat-pin-btn" onclick="event.stopPropagation(); toggleChatPin('${escHtml(gid)}')" aria-label="${pinned ? t('chat.unpin') : t('chat.pin')}" title="${pinned ? t('chat.unpin') : t('chat.pin')}"><i class="fa-solid fa-thumbtack"></i></button>
          </div>
        </div>
      </div>`;
  }

  function requestRowHtml(reqKey, req) {
    const name = escHtml(req.fromName || t('friend.noName'));
    const fromUid = escHtml(req.from);
    return `
      <div class="card card-padded" style="display:flex;align-items:center;gap:10px;background:var(--grad-cream);">
        <div style="width:38px;height:38px;border-radius:50%;background:var(--blush);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0;">✉️</div>
        <div style="flex:1;min-width:0;">
          <div style="font-weight:600;color:var(--berry);font-size:13px;">${name}</div>
          <div style="font-size:10.5px;color:var(--soft);">${t('ui.083')}</div>
        </div>
        <div style="display:flex;gap:6px;flex-shrink:0;">
          <button onclick="acceptFriendRequest('${escHtml(reqKey)}','${fromUid}','${name.replace(/'/g,"&#39;")}')" class="btn btn-primary" style="padding:7px 12px;font-size:11px;">${t('ui.r033')}</button>
          <button onclick="declineFriendRequest('${escHtml(reqKey)}','${fromUid}')" class="btn btn-ghost" style="padding:7px 10px;font-size:11px;">×</button>
        </div>
      </div>`;
  }

  // ── Глобальный чат сообщества: один общий канал для всех учениц и Мади ──
  // Живёт в chats/g_community (обычная группа), но: не входит в users/*/groups,
  // строка рендерится отдельно поверх списка у ВСЕХ, веерных unread-записей нет
  // (сообщество большое) — «новое» считается локально от communityReadAt.
  const COMMUNITY_GID = 'g_community';
  // Личный Telegram Мади — кнопка в шапке чата с ней + в автоответе на заявку тарифа.
  const KM_TELEGRAM_URL = 'https://t.me/mabdullaeva33';
  // «Новое» в сообществе считаем локально (веерных unread-записей нет — чат большой).
  // Сравниваем по СЕРВЕРНОМУ времени последнего сообщения (meta.lastAt), а не по
  // Date.now(): раньше «прочитано» писалось часами моего устройства, а «новое» —
  // часами другого ученика, и при расхождении часов «new» не гас (отзыв 09.07).
  // И не считаем новым СВОЁ последнее сообщение (lastFrom === me).
  function _communityHasNew() {
    const meta = _chatMetaCache[COMMUNITY_GID] || {};
    const lastRead = UStore.get('communityReadAt', 0) || 0;
    return !!(meta.lastAt && meta.lastAt > lastRead && meta.lastFrom && meta.lastFrom !== myUid());
  }
  function _markCommunityRead() {
    const meta = _chatMetaCache[COMMUNITY_GID] || {};
    try { UStore.set('communityReadAt', meta.lastAt || Date.now()); } catch (_) {}
  }
  function communityRowHtml() {
    const meta = _chatMetaCache[COMMUNITY_GID] || {};
    const hasNew = _communityHasNew();
    const preview = meta.lastMessage
      ? `${meta.lastFromName ? escHtml(meta.lastFromName) + ': ' : ''}${escHtml(meta.lastMessage)}`
      : t('comm.preview');
    const timeLabel = chatListTimeLabel(meta.lastAt);
    return `
      <div class="card card-press chat-list-row" onclick="openCommunityChat()" style="background:linear-gradient(135deg, rgba(var(--accent-rgb),.10), var(--card)); border-color:rgba(var(--accent-rgb),.28);">
        <div class="friend-avatar-wrap"><div class="chat-row-av chat-row-av-initial" style="background:var(--grad-coral); color:#FFF7F9;">🌍</div></div>
        <div class="chat-row-main">
          <div class="chat-row-top">
            <span class="chat-row-name">${t('comm.title')} <span style="font-size:9.5px;color:var(--coral);font-weight:800;letter-spacing:.08em;">${t('comm.badge')}</span></span>
            <span class="chat-row-time ${hasNew ? 'unread' : ''}">${timeLabel}</span>
          </div>
          <div class="chat-row-bottom">
            <span class="chat-row-preview">${preview}</span>
            ${hasNew ? '<span class="chat-unread-badge">new</span>' : ''}
          </div>
        </div>
      </div>`;
  }
  async function openCommunityChat() {
    if (!isLoggedInForChat()) { toast(t('ui.102')); return; }
    if (typeof _db === 'undefined') { toast(t('ui.243')); return; }
    const me = myUid();
    try {
      const metaRef = _db.ref(`chats/${COMMUNITY_GID}/meta`);
      const snap = await metaRef.once('value');
      if (!snap.val()) {
        await metaRef.set({ group: true, community: true, title: 'Чат сообщества', owner: 'system', createdAt: Date.now(), members: { [me]: true } });
      } else {
        // членство нужно для отметок прочтения/печатает — дописываем себя тихо
        metaRef.child('members/' + me).set(true).catch(() => {});
      }
    } catch (_) {}
    _markCommunityRead();
    openGroupChat(COMMUNITY_GID, t('comm.title'));
  }

  let _renderFriendsSeq = 0; // drop stale async renders (meta fetches race otherwise)
  // Подпись мет чатов: фоновое обновление перерисовывает список ТОЛЬКО когда
  // что-то реально изменилось (иначе экран зря «мигает» и сбрасывает скролл).
  function _chatMetaSig(keys) {
    return keys.map(k => { const m = _chatMetaCache[k] || {}; return k + ':' + (m.lastAt || 0); }).join('|');
  }
  async function renderFriendsAndChat(fromBgRefresh) {
    const slot = document.getElementById('friends-chat-section');
    if (!slot) return;
    const seq = ++_renderFriendsSeq;
    if (!_usersDirCache) await loadUsersDirectory();
    if (isAdmin()) { renderAdminChatList(fromBgRefresh); return; }
    const friends = _friendsCache || {};
    const groups = _groupsCache || {};
    const inbox = _inboxCache || {};
    if (!_chatLastAtLoaded) loadChatLastAt();
    const me = myUid();
    // Меты чатов (последнее сообщение + время). Cache-first: при повторном заходе
    // рисуем МГНОВЕННО из кэша, а свежие меты тянем фоном и тихо перерисовываем
    // только при реальных изменениях. Первый заход за сессию — ждём сеть (иначе пусто).
    if (me && me !== 'guest' && !fromBgRefresh) {
      const items = [
        { key: COMMUNITY_GID, chatId: COMMUNITY_GID },
        ...Object.keys(friends).map(uid => ({ key: uid, chatId: chatIdFor(me, uid) })),
        ...Object.keys(groups).map(gid => ({ key: gid, chatId: gid }))
      ];
      if (!Object.keys(_chatMetaCache).length) {
        await loadChatMetas(items);
      } else {
        const sigBefore = _chatMetaSig(items.map(i => i.key));
        loadChatMetas(items).then(() => {
          if (seq !== _renderFriendsSeq) return;               // уже начался новый рендер
          if (_curScreen !== 'social') return;                 // ушли с экрана
          if (document.getElementById('chat-page')) return;    // открыта переписка
          if (_chatMetaSig(items.map(i => i.key)) === sigBefore) return;
          renderFriendsAndChat(true);
        });
      }
    }
    if (seq !== _renderFriendsSeq) return; // a newer render started while we awaited
    // Telegram order: the conversation with the newest message on top.
    const lastTs = key => {
      const meta = _chatMetaCache[key] || {};
      return meta.lastAt || _chatLastAt[key] ||
        (friends[key] && friends[key].since) || (groups[key] && groups[key].since) || 0;
    };
    const convos = [
      ...Object.keys(friends).map(uid => ({ kind: 'dm', key: uid })),
      ...Object.keys(groups).map(gid => ({ kind: 'group', key: gid }))
    ].sort((a, b) => {
      // Закреплённые — всегда вверху, затем по времени последнего сообщения
      const pa = isChatPinned(a.key) ? 1 : 0, pb = isChatPinned(b.key) ? 1 : 0;
      if (pa !== pb) return pb - pa;
      return lastTs(b.key) - lastTs(a.key);
    });
    const requests = Object.entries(inbox).filter(([k, v]) => v && v.type === 'friend_request');

    const requestsHtml = requests.length
      ? `<div style="font-size:10px;letter-spacing:.18em;color:var(--coral);font-weight:700;margin:4px 4px 8px;">${t('ui.r034')} · ${requests.length}</div>
         <div style="display:grid;gap:8px;margin-bottom:14px;">${requests.map(([k,r]) => requestRowHtml(k, r)).join('')}</div>`
      : '';

    // stagger-in — только при ПЕРВОМ наполнении списка: повторная перерисовка
    // (пришло сообщение, обновились меты) переигрывала входную анимацию всех
    // строк — выглядело как «список перезагрузился и мигает».
    const staggerCls = slot.childElementCount ? '' : 'stagger-in';
    const listHtml = convos.length
      ? `<div class="${staggerCls}" style="display:grid;gap:8px;">${communityRowHtml()}${convos.map(c => c.kind === 'group' ? groupRowHtml(c.key, groups[c.key]) : friendRowHtml(c.key, friends[c.key])).join('')}</div>`
      : `<div style="display:grid;gap:8px;margin-bottom:10px;">${communityRowHtml()}</div>
         <div class="card" style="text-align:center; padding:26px 18px 22px; background:linear-gradient(160deg, var(--card), var(--paper));">
           <img src="assets/bear3.png" alt="" style="width:92px; margin:0 auto 4px; display:block; filter:drop-shadow(0 8px 14px rgba(92,42,51,.18));" onerror="this.style.display='none'">
           <div class="display" style="font-size:18px; color:var(--berry);">${t('ui.084')}</div>
           <div style="font-size:12px; color:var(--soft); margin-top:6px; line-height:1.55; max-width:260px; margin-left:auto; margin-right:auto;">
             ${t('ui.t007')}
           </div>
           <div style="display:grid; gap:8px; margin-top:14px; text-align:left; max-width:280px; margin-left:auto; margin-right:auto;">
             <div style="display:flex; align-items:center; gap:10px; font-size:12px; color:var(--berry);"><span style="width:30px; height:30px; flex-shrink:0; border-radius:10px; background:var(--blush); display:flex; align-items:center; justify-content:center;">💬</span> ${t('ui.085')}</div>
             <div style="display:flex; align-items:center; gap:10px; font-size:12px; color:var(--berry);"><span style="width:30px; height:30px; flex-shrink:0; border-radius:10px; background:var(--blush); display:flex; align-items:center; justify-content:center;">🔥</span> ${t('ui.086')}</div>
             <div style="display:flex; align-items:center; gap:10px; font-size:12px; color:var(--berry);"><span style="width:30px; height:30px; flex-shrink:0; border-radius:10px; background:var(--blush); display:flex; align-items:center; justify-content:center;">👩‍🏫</span> ${t('ui.087')}</div>
           </div>
           <button onclick="openAddFriendModal()" class="btn btn-primary" style="margin-top:16px;"><i class="fa-solid fa-user-plus" style="font-size:11px;"></i> ${t('ui.088')}</button>
         </div>`;

    // Поисковик по своим друзьям/группам (фильтрация на клиенте — список и так
    // уже загружен целиком; поиск НОВЫХ людей — отдельная модалка openAddFriendModal).
    const searchHtml = convos.length >= 4 ? `
      <div style="position:relative; margin-bottom:12px;">
        <i class="fa-solid fa-magnifying-glass" style="position:absolute; left:14px; top:50%; transform:translateY(-50%); color:var(--soft); font-size:13px; pointer-events:none;"></i>
        <input id="social-search-input" class="input" placeholder="${escAttr(t('social.search.ph'))}" oninput="filterSocialList(this.value)" style="padding-left:38px; font-size:13px;">
      </div>
      <div id="social-search-empty" style="display:none; text-align:center; padding:20px 10px; color:var(--soft); font-size:12.5px;">${t('social.search.empty')}</div>
    ` : '';
    const finalHtml = `
      <div id="week-leaderboard"></div>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:0 4px;margin-bottom:10px;">
        <div style="font-size:10px;letter-spacing:.2em;color:var(--soft);">${t('ui.t008')} ${convos.length ? `<span style="color:var(--coral);font-weight:700;letter-spacing:.04em;">${convos.length}</span>` : ''}</div>
        <div style="display:flex;gap:6px;">
          ${Object.keys(friends).length ? `<button onclick="openCreateGroupModal()" class="chip" style="font-size:11px;padding:5px 12px;cursor:pointer;border:none;background:var(--blush);color:var(--berry);"><i class="fa-solid fa-user-group" style="font-size:10px;"></i> ${t('ui.089')}</button>` : ''}
          <button onclick="openAddFriendModal()" class="chip chip-coral" style="font-size:11px;padding:5px 12px;cursor:pointer;border:none;"><i class="fa-solid fa-user-plus" style="font-size:10px;"></i> ${t('ui.090')}</button>
        </div>
      </div>
      ${pushPermissionCtaHtml()}
      ${searchHtml}
      ${requestsHtml}
      ${listHtml}
    `;
    // Ничего не изменилось — не трогаем DOM (unreadFrom дёргает этот рендер
    // на каждое сообщение, включая эхо собственного «прочитано»).
    if (slot._lastListHtml !== finalHtml) {
      // Реальное изменение (новое сообщение и т.п.) полностью перерисует список —
      // не даём это стереть то, что ученица уже набрала в поиске.
      const prevQuery = document.getElementById('social-search-input')?.value || '';
      slot._lastListHtml = finalHtml;
      slot.innerHTML = finalHtml;
      if (prevQuery) {
        const inp = document.getElementById('social-search-input');
        if (inp) { inp.value = prevQuery; filterSocialList(prevQuery); }
      }
    }
    renderWeekLeaderboard();
  }
  // Фильтр списка друзей/групп по имени — сообщество и заявки в друзья всегда
  // остаются видимыми (у них нет data-chat-name), фильтруются только строки чатов.
  function filterSocialList(q) {
    const query = (q || '').trim().toLowerCase();
    const slot = document.getElementById('friends-chat-section');
    if (!slot) return;
    let anyMatch = !query;
    slot.querySelectorAll('[data-chat-name]').forEach(row => {
      const match = !query || row.getAttribute('data-chat-name').includes(query);
      row.style.display = match ? '' : 'none';
      if (match) anyMatch = true;
    });
    const emptyEl = document.getElementById('social-search-empty');
    if (emptyEl) emptyEl.style.display = (query && !anyMatch) ? '' : 'none';
  }

  // ── Лидерборд недели: я + друзья по XP с понедельника ──
  function _weekStartIso() {
    const d = new Date();
    const day = (d.getDay() + 6) % 7; // 0 = понедельник
    d.setDate(d.getDate() - day);
    return d.toISOString().slice(0, 10);
  }
  function _weekXpFrom(xpByDay) {
    const start = _weekStartIso();
    let sum = 0;
    Object.entries(xpByDay || {}).forEach(([k, v]) => { if (k >= start) sum += (+v || 0); });
    return sum;
  }
  // Рейтинг. Две оси: охват (друзья / глобальный) и период (неделя / всё время).
  let _lbMode = 'week';      // 'week' — XP с понедельника, 'all' — общий накопленный XP
  let _lbScope = 'friends';  // 'friends' — я + друзья, 'global' — все ученики
  let _lbFriendRows = null;  // кэш строк друзей (с week/all) — переключаем период без перезагрузки
  let _lbGlobalRows = null;  // кэш строк глобального рейтинга
  function setLeaderboardMode(mode) { _lbMode = (mode === 'all') ? 'all' : 'week'; paintLeaderboard(); }
  function setLbScope(scope) { _lbScope = (scope === 'global') ? 'global' : 'friends'; paintLeaderboard(); }
  async function renderWeekLeaderboard() {
    const slot = document.getElementById('week-leaderboard');
    if (!slot) return;
    const me = Store.get('user');
    if (!me || me.guest || typeof _db === 'undefined') { slot.innerHTML = ''; _lbFriendRows = _lbGlobalRows = null; return; }
    // Мгновенный показ из кэша прошлого визита — свежие данные ниже тихо перерисуют
    if (_lbFriendRows || _lbGlobalRows) paintLeaderboard();
    const myUid = firebaseUserId();
    const myRow = { uid: myUid, name: me.name || 'Я', me: true, week: _weekXpFrom(stats.xpByDay), all: stats.xp || 0 };

    // — Друзья: я + друзья (свежая стата каждого из облака) —
    const friends = _friendsCache || {};
    const fids = Object.keys(friends);
    let friendRows = null;
    if (fids.length) {
      friendRows = [myRow];
      await Promise.all(fids.map(async fid => {
        try {
          const snap = await _db.ref('users/' + fid + '/stats').once('value');
          const s = snap.val() || {};
          friendRows.push({ uid: fid, name: (friends[fid] && friends[fid].name) || 'Друг', week: _weekXpFrom(s.xpByDay), all: (+s.xp || 0) });
        } catch (_) {}
      }));
    }
    _lbFriendRows = friendRows;

    // — Глобальный: все ученики из общего справочника (без админов) —
    if (!_usersDirCache) { try { await loadUsersDirectory(); } catch (_) {} }
    const dir = _usersDirCache || {};
    const globalRows = [];
    Object.entries(dir).forEach(([uid, u]) => {
      if (!u || u.isAdmin) return;            // учителей в рейтинг учеников не включаем
      if (uid === myUid) return;              // себя добавим из живой статы ниже
      const s = u.stats || {};
      globalRows.push({ uid, name: u.name || t('feed.studentName'), week: _weekXpFrom(s.xpByDay), all: (+s.xp || 0) });
    });
    globalRows.push(myRow);
    _lbGlobalRows = globalRows;

    // Выбор охвата по умолчанию: если друзей нет — показываем глобальный.
    if (!fids.length && _lbScope === 'friends') _lbScope = 'global';
    // Рейтинг приезжает асинхронно и вставляется НАД списком чатов. Браузерное
    // «scroll anchoring» иначе удерживает чаты на месте и прячет верх рейтинга под
    // шапкой («обрезается»). Возвращаем скролл туда, где он был до вставки.
    const keepY = _getScroll();
    paintLeaderboard();
    _setScroll(keepY);
    requestAnimationFrame(() => _setScroll(keepY));
  }
  function paintLeaderboard() {
    const slot = document.getElementById('week-leaderboard');
    if (!slot) return;
    const hasFriends = !!(_lbFriendRows && _lbFriendRows.length);
    const globalHasRivals = !!(_lbGlobalRows && _lbGlobalRows.length > 1);
    if (!hasFriends && !globalHasRivals) { slot.innerHTML = ''; return; } // соревноваться не с кем

    const mode = _lbMode;
    const scope = (_lbScope === 'friends' && !hasFriends) ? 'friends' : _lbScope; // оставим вкладку, покажем подсказку
    const src = scope === 'global' ? (_lbGlobalRows || []) : (_lbFriendRows || []);
    const rows = src.map(r => ({ ...r, xp: mode === 'all' ? (r.all || 0) : (r.week || 0) })).sort((a, b) => b.xp - a.xp);
    const sub = mode === 'all' ? t('xp.allTime') : t('xp.weekly');
    const medal = i => i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `<span style="font-size:11px;color:var(--hush);font-weight:700;">${i + 1}</span>`;
    const myIdx = rows.findIndex(r => r.me);
    const rowHtml = (r, i) => `
      <div style="display:flex; align-items:center; gap:10px; padding:8px 10px; border-radius:12px; background:${r.me ? 'rgba(var(--accent-rgb),.10)' : 'transparent'}; ${r.me ? 'box-shadow: inset 0 0 0 1px rgba(var(--accent-rgb),.25);' : ''}">
        <span style="width:22px; text-align:center; font-size:15px;">${medal(i)}</span>
        <span style="flex:1; min-width:0; font-weight:600; font-size:13px; color:var(--berry); overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${escHtml(r.name)}${r.me ? ' <span style="font-size:10px;color:var(--coral);">· это ты</span>' : ''}</span>
        <span style="font-weight:800; font-size:13px; color:${i === 0 ? 'var(--gold)' : 'var(--soft)'};">${r.xp} XP</span>
      </div>`;

    let body;
    if (scope === 'friends' && !hasFriends) {
      body = `<div style="text-align:center; font-size:12px; color:var(--soft); padding:14px 8px; line-height:1.55;">
          ${t('ui.t009')}<br>
          <button onclick="openAddFriendModal()" class="chip chip-coral" style="margin-top:10px; font-size:11px; padding:6px 14px; cursor:pointer; border:none;"><i class="fa-solid fa-user-plus" style="font-size:10px;"></i> ${t('ui.088')}</button>
        </div>`;
    } else {
      const top = rows.slice(0, 5).map((r, i) => rowHtml(r, i)).join('');
      // Если я вне топ-5 (актуально для глобального) — показать мою строку отдельно с реальным местом.
      const tail = (myIdx >= 5)
        ? `<div style="text-align:center; font-size:11px; color:var(--hush); margin:2px 0;">···</div>${rowHtml(rows[myIdx], myIdx)}`
        : '';
      const hint = myIdx > 0
        ? `<div style="text-align:center; font-size:11px; color:var(--soft); margin-top:8px;">${t('ui.r035',{name: escHtml(rows[myIdx - 1].name), xp: rows[myIdx - 1].xp - rows[myIdx].xp + 1})}</div>`
        : (myIdx === 0 ? `<div style="text-align:center; font-size:11px; color:var(--gold-ink); margin-top:8px;">Ты впереди всех — 화이팅! 🌟</div>` : '');
      body = `<div style="display:grid; gap:6px;">${top}${tail}</div>${hint}`;
    }

    const count = scope === 'global' ? rows.length : Math.max(0, rows.length);
    slot.innerHTML = `
      <div class="card card-padded" style="margin-bottom:16px; background:linear-gradient(160deg, var(--card), var(--paper));">
        <div class="auth-tabs" style="margin-bottom:8px;">
          <button type="button" class="auth-tab ${scope === 'friends' ? 'auth-tab-active' : ''}" onclick="setLbScope('friends')">${t('ui.091')}</button>
          <button type="button" class="auth-tab ${scope === 'global' ? 'auth-tab-active' : ''}" onclick="setLbScope('global')">${t('ui.092')}</button>
        </div>
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:8px;">
          <div style="display:flex; gap:6px;">
            <button type="button" class="lb-chip ${mode === 'week' ? 'lb-chip-on' : ''}" onclick="setLeaderboardMode('week')">${t('ui.093')}</button>
            <button type="button" class="lb-chip ${mode === 'all' ? 'lb-chip-on' : ''}" onclick="setLeaderboardMode('all')">${t('ui.094')}</button>
          </div>
          <div style="font-size:10px; color:var(--hush); white-space:nowrap;">${sub}${scope === 'global' ? ` · ${count} 🌍` : ''}</div>
        </div>
        ${body}
      </div>`;
  }

  function pushPermissionCtaHtml() {
    if (!_messaging || !('Notification' in window)) return '';
    if (!_VAPID_KEY || _VAPID_KEY.startsWith('REPLACE_')) return '';
    if (Notification.permission === 'granted') return '';
    if (Notification.permission === 'denied') {
      return `<div style="background:rgba(var(--rose-rgb),.12);border:1px dashed rgba(var(--rose-rgb),.5);border-radius:14px;padding:10px 12px;margin-bottom:12px;font-size:11.5px;color:var(--bad-ink);text-align:center;">
        ${t('ui.t010')}
      </div>`;
    }
    return `<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px;margin-bottom:12px;display:flex;align-items:center;gap:10px;">
      <div style="font-size:22px;">🔔</div>
      <div style="flex:1;min-width:0;">
        <div style="font-weight:600;color:var(--berry);font-size:12.5px;">${t('ui.095')}</div>
        <div style="font-size:10.5px;color:var(--soft);margin-top:1px;">${t('ui.096')}</div>
      </div>
      <button onclick="askPushPermission()" class="btn btn-primary" style="padding:7px 12px;font-size:11px;flex-shrink:0;">${t('ui.097')}</button>
    </div>`;
  }

  async function renderAdminChatList(fromBgRefresh) {
    const slot = document.getElementById('friends-chat-section');
    if (!slot) return;
    const seq = ++_renderFriendsSeq;
    const dir = _usersDirCache || {};
    const me = myUid();
    const groups = _groupsCache || {};
    // Fresh previews — cache-first: повторный заход рисуется мгновенно из кэша,
    // свежие меты (по одному запросу на ученицу — дорого) тянутся фоном.
    const studentUids = Object.keys(dir).filter(uid => !(dir[uid] && dir[uid].isAdmin) && uid !== me);
    if (me && me !== 'guest' && !fromBgRefresh) {
      const items = [
        { key: COMMUNITY_GID, chatId: COMMUNITY_GID },
        ...studentUids.map(uid => ({ key: uid, chatId: chatIdFor(me, uid) })),
        ...Object.keys(groups).map(gid => ({ key: gid, chatId: gid }))
      ];
      if (!Object.keys(_chatMetaCache).length) {
        await loadChatMetas(items);
      } else {
        const sigBefore = _chatMetaSig(items.map(i => i.key));
        loadChatMetas(items).then(() => {
          if (seq !== _renderFriendsSeq) return;
          if (_curScreen !== 'social') return;
          if (document.getElementById('chat-page')) return;
          if (_chatMetaSig(items.map(i => i.key)) === sigBefore) return;
          renderAdminChatList(true);
        });
      }
    }
    if (!document.getElementById('friends-chat-section')) return;
    if (seq !== _renderFriendsSeq) return;
    const students = studentUids
      .map(uid => ({ uid, ...dir[uid] }))
      .sort((a, b) => {
        const pa = isChatPinned(a.uid) ? 1 : 0, pb = isChatPinned(b.uid) ? 1 : 0;
        if (pa !== pb) return pb - pa;
        const aUnread = unreadCountFor(a.uid);
        const bUnread = unreadCountFor(b.uid);
        if (aUnread !== bUnread) return bUnread - aUnread;
        const aAt = (_chatMetaCache[a.uid] && _chatMetaCache[a.uid].lastAt) || 0;
        const bAt = (_chatMetaCache[b.uid] && _chatMetaCache[b.uid].lastAt) || 0;
        if (aAt !== bAt) return bAt - aAt;
        return (b.lastSeen || 0) - (a.lastSeen || 0);
      });

    const groupRows = Object.keys(groups)
      .sort((a, b) => ((_chatMetaCache[b] && _chatMetaCache[b].lastAt) || 0) - ((_chatMetaCache[a] && _chatMetaCache[a].lastAt) || 0))
      .map(gid => groupRowHtml(gid, groups[gid])).join('');

    // stagger-in — только при первом наполнении; сигнатура гасит холостые
    // перерисовки (unreadFrom дёргает список на каждое сообщение). См. renderFriendsAndChat.
    const staggerCls = slot.childElementCount ? '' : 'stagger-in';
    const listHtml = students.length
      ? `<div class="${staggerCls}" style="display:grid;gap:8px;">${communityRowHtml()}${groupRows}${students.map(s => adminChatRowHtml(s)).join('')}</div>`
      : `<div style="display:grid;gap:8px;margin-bottom:10px;">${communityRowHtml()}</div>
         <div style="text-align:center;padding:18px 12px;color:var(--soft);font-size:12px;background:var(--blush);border:1px dashed var(--line);border-radius:14px;">${t('ui.098')}</div>`;

    const finalHtml = `
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;padding:0 4px;margin-bottom:10px;">
        <div style="font-size:10px;letter-spacing:.2em;color:var(--soft);">${t('ui.099')} <span style="color:var(--coral);font-weight:700;letter-spacing:.04em;">${students.length}</span></div>
        <div style="display:flex;gap:6px;">
          <button onclick="adminOpenFullRating()" class="chip" style="font-size:11px;padding:5px 12px;cursor:pointer;border:none;background:var(--blush);color:var(--berry);">🏆 Рейтинг</button>
          <button onclick="openCreateGroupModal()" class="chip" style="font-size:11px;padding:5px 12px;cursor:pointer;border:none;background:var(--blush);color:var(--berry);"><i class="fa-solid fa-user-group" style="font-size:10px;"></i> ${t('ui.089')}</button>
          <button onclick="refreshAdminChatList()" class="chip" style="font-size:11px;padding:5px 12px;cursor:pointer;border:none;background:var(--blush);color:var(--berry);"><i class="fa-solid fa-rotate" style="font-size:10px;"></i> ${t('ui.100')}</button>
        </div>
      </div>
      ${listHtml}
    `;
    if (slot._lastListHtml !== finalHtml) {
      slot._lastListHtml = finalHtml;
      slot.innerHTML = finalHtml;
    }
  }

  function adminChatRowHtml(u) {
    const name = escHtml(u.name || t('friend.noName'));
    const unread = unreadCountFor(u.uid);
    const xp = (u.stats && u.stats.xp) || 0;
    const lvl = getLevel(xp);
    const rank = getRank(lvl);
    const initial = escHtml((u.name || '?').charAt(0).toUpperCase());
    const online = u.lastSeen && (Date.now() - u.lastSeen) < ONLINE_WINDOW_MS;
    const meta = _chatMetaCache[u.uid] || {};
    const avatarInner = u.avatar
      ? `<div class="photo-zoom chat-row-av" style="background:url(${u.avatar}) center/cover no-repeat;"></div>`
      : `<div class="chat-row-av chat-row-av-initial">${initial}</div>`;
    const avatar = `<div class="friend-avatar-wrap">${avatarInner}${online ? `<span class="friend-online-dot" title="${t('chat.online')}"></span>` : ''}</div>`;
    let preview;
    if (meta.lastMessage) {
      const mine = meta.lastFrom === myUid();
      preview = `${mine ? `<span class="chat-row-me">${t('chat.you')}</span> ` : ''}${escHtml(meta.lastMessage)}`;
    } else {
      preview = `${escHtml(u.email || '')} · 🔥 ${(u.stats && u.stats.streak) || 0} · ${xp} XP`;
    }
    const timeLabel = chatListTimeLabel(meta.lastAt);
    const pinned = isChatPinned(u.uid);
    // Чип уровня корейского — тап открывает пикер для этой ученицы (не открывая чат)
    const lvlObj = levelById(u.level || '');
    const lvlChip = `<button onclick="event.stopPropagation(); adminPickStudentLevel('${escHtml(u.uid)}','${u.level || ''}')" class="ko" title="${escAttr(t('lvl.change'))}" style="flex-shrink:0; font-size:9.5px; font-weight:700; padding:2px 8px; border-radius:999px; border:1px solid var(--line-strong); background:var(--paper); color:var(--coral); cursor:pointer; font-family:inherit;">${lvlObj ? escHtml(lvlObj.code) : '<i class="fa-solid fa-graduation-cap" style="font-size:9px;"></i>'}</button>`;
    return `
      <div class="card card-press chat-list-row${pinned ? ' chat-pinned' : ''}" onclick="openChat('${escHtml(u.uid)}','${name.replace(/'/g,"&#39;")}')">
        ${avatar}
        <div class="chat-row-main">
          <div class="chat-row-top">
            <span class="chat-row-name">${pinned ? '<i class="fa-solid fa-thumbtack chat-pin-i"></i> ' : ''}${name} <span style="font-size:10.5px;color:var(--coral);font-weight:600;">${rank.emoji} Lv ${lvl}</span>${u.sonbae ? ' <span class="chip chip-gold" style="font-size:9px;padding:1px 6px;" title="선배">🎓</span>' : ''}</span>
            <span class="chat-row-time ${unread > 0 ? 'unread' : ''}">${timeLabel}</span>
          </div>
          <div class="chat-row-bottom">
            <span class="chat-row-preview">${preview}</span>
            ${unread > 0 ? `<span class="chat-unread-badge">${unread > 99 ? '99+' : unread}</span>` : ''}
            ${lvlChip}
            <button class="chat-pin-btn" onclick="event.stopPropagation(); toggleChatPin('${escHtml(u.uid)}')" aria-label="${pinned ? t('chat.unpin') : t('chat.pin')}" title="${pinned ? t('chat.unpin') : t('chat.pin')}"><i class="fa-solid fa-thumbtack"></i></button>
          </div>
        </div>
      </div>`;
  }
  // Админ: открыть пикер уровня для ученицы и сохранить выбор в её облачный профиль
  function adminPickStudentLevel(uid, currentId) {
    if (!ensureAdminAccess()) return;
    openLevelPicker(currentId || '', id => adminSetUserLevel(uid, id));
  }
  function adminSetUserLevel(uid, id) {
    if (!ensureAdminAccess() || typeof _db === 'undefined' || !uid) return;
    _db.ref('users/' + uid + '/level').set(id || '')
      .then(() => {
        // Чат-лист читает тонкий usersPublic — без зеркала чип уровня откатывался бы
        // к старому после протухания кэша (ученица обновит своё зеркало только при входе).
        _db.ref('usersPublic/' + uid + '/level').set(id || null).catch(() => {});
        if (_usersDirCache && _usersDirCache[uid]) _usersDirCache[uid].level = id || '';
        toast(t('lvl.changed'), 'var(--sage)');
        renderAdminChatList();
      })
      .catch(e => { console.warn('set student level failed:', e); toast(t('ui.101')); });
  }

  async function refreshAdminChatList() {
    // Справочник теперь кэшируется и в localStorage (TTL 10 мин) — без del()
    // loadUsersDirectory вернула бы тот же кэш, и «Обновить» ничего не обновляло бы.
    Store.del('usersDirCacheV1');
    _usersDirCache = null;
    _adminUsersCache = {};
    _adminUsersCacheAt = 0;
    await loadUsersDirectory();
    renderAdminChatList();
    toast('Список обновлён 🌸', 'var(--sage)');
  }

  // ── Админ: полный рейтинг всех учениц (весь список, не топ-5) ──
  let _admRatingMode = 'all';
  function adminOpenFullRating(mode) {
    if (!ensureAdminAccess()) return;
    if (mode) _admRatingMode = (mode === 'week') ? 'week' : 'all';
    const dir = _usersDirCache || {};
    const rows = Object.entries(dir)
      .filter(([, u]) => u && !u.isAdmin)
      .map(([uid, u]) => {
        const s = u.stats || {};
        return { uid, name: u.name || t('grp.defStudent'), avatar: u.avatar || '', week: _weekXpFrom(s.xpByDay), all: (+s.xp || 0), streak: (+s.streak || 0) };
      })
      .sort((a, b) => (_admRatingMode === 'week' ? (b.week - a.week || b.all - a.all) : (b.all - a.all || b.week - a.week)));
    const medal = i => i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : `<span style="font-size:11px;color:var(--hush);font-weight:700;">${i + 1}</span>`;
    const rowHtml = (r, i) => {
      const lvl = getLevel(r.all);
      const av = r.avatar
        ? `<div style="width:34px;height:34px;border-radius:50%;background:url(${r.avatar}) center/cover no-repeat;flex-shrink:0;border:2px solid var(--rose);"></div>`
        : `<div style="width:34px;height:34px;border-radius:50%;background:var(--paper);flex-shrink:0;border:2px solid var(--rose);display:flex;align-items:center;justify-content:center;font-size:13px;color:var(--coral);font-weight:700;">${escHtml((r.name || '?').charAt(0).toUpperCase())}</div>`;
      return `
        <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:12px;background:${i < 3 ? 'rgba(201,165,92,.08)' : 'transparent'};">
          <span style="width:24px;text-align:center;font-size:15px;flex-shrink:0;">${medal(i)}</span>
          ${av}
          <div style="flex:1;min-width:0;">
            <div style="font-weight:600;font-size:13px;color:var(--berry);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(r.name)}</div>
            <div style="font-size:10.5px;color:var(--soft);">Lv ${lvl} · 🔥 ${r.streak}</div>
          </div>
          <span style="font-weight:800;font-size:13px;color:${i === 0 ? 'var(--gold)' : 'var(--soft)'};flex-shrink:0;">${_admRatingMode === 'week' ? r.week : r.all} XP</span>
        </div>`;
    };
    const chip = (m2, label) => `<button type="button" class="lb-chip ${_admRatingMode === m2 ? 'lb-chip-on' : ''}" onclick="adminOpenFullRating('${m2}')">${label}</button>`;
    document.getElementById('admin-rating-modal')?.remove();
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'admin-rating-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-height:86vh;overflow-y:auto;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;">
          <div>
            <div class="page-eyebrow">🏆 Рейтинг учениц</div>
            <div class="display" style="font-size:20px;color:var(--berry);margin-top:2px;">Весь список · ${rows.length}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px;line-height:1;color:var(--soft);cursor:pointer;padding:4px;">×</div>
        </div>
        <div style="display:flex;gap:6px;margin-bottom:10px;">
          ${chip('week', 'Эта неделя')}${chip('all', 'За всё время')}
        </div>
        <div style="display:grid;gap:4px;">${rows.map(rowHtml).join('') || `<div style="text-align:center;color:var(--soft);font-size:12px;padding:20px;">Пока нет учениц</div>`}</div>
      </div>`;
    document.body.appendChild(m);
  }

  function openAddFriendModal() {
    if (!isLoggedInForChat()) { toast(t('friend.loginNeeded')); return; }
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'add-friend-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:380px;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px;">
          <div>
            <div class="page-eyebrow">${t('friend.find.eyebrow')}</div>
            <div class="display" style="font-size:20px;color:var(--berry);margin-top:2px;">${t('friend.find.title')}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px;color:var(--soft);cursor:pointer;line-height:1;padding:2px 6px;">×</div>
        </div>
        <input id="add-friend-search" class="input" placeholder="${escAttr(t('friend.find.ph'))}" oninput="filterAddFriend()" style="font-size:13px;">
        <div id="add-friend-results" style="display:grid;gap:8px;margin-top:14px;max-height:340px;overflow-y:auto;">
          <div style="text-align:center;padding:18px;color:var(--soft);font-size:12px;">${t('common.loading')}</div>
        </div>
      </div>`;
    document.body.appendChild(m);
    setTimeout(() => { document.getElementById('add-friend-search')?.focus(); }, 80);
    filterAddFriend();
  }

  async function filterAddFriend() {
    const q = document.getElementById('add-friend-search')?.value || '';
    const list = document.getElementById('add-friend-results');
    if (!list) return;
    const users = await searchUsersByName(q);
    const friends = _friendsCache || {};
    if (!users.length) {
      list.innerHTML = `<div style="text-align:center;padding:18px;color:var(--soft);font-size:12px;">${t('friend.none')}</div>`;
      return;
    }
    list.innerHTML = users.map(u => {
      const isFriend  = !!friends[u.uid];
      const isPending = !!(_outgoingCache && _outgoingCache[u.uid]);
      const isSending = _sendingFriendReq.has(u.uid);
      const initial = escHtml((u.name || '?').charAt(0).toUpperCase());
      const avatar = u.avatar
        ? `<div class="photo-zoom" style="width:38px;height:38px;border-radius:50%;background:url(${u.avatar}) center/cover no-repeat;flex-shrink:0;border:1.5px solid var(--rose);"></div>`
        : `<div style="width:38px;height:38px;border-radius:50%;background:var(--paper);flex-shrink:0;border:1.5px solid var(--rose);display:flex;align-items:center;justify-content:center;font-size:14px;color:var(--coral);font-weight:700;">${initial}</div>`;
      let actionHtml;
      if (isFriend) {
        actionHtml = `<span class="chip chip-sage" style="font-size:10px;flex-shrink:0;">${t('friend.isFriend')}</span>`;
      } else if (isPending) {
        actionHtml = `
          <div style="display:flex;gap:5px;flex-shrink:0;align-items:center;">
            <span class="chip" style="font-size:10px;background:rgba(201,165,92,.18);color:var(--gold-ink);border:1px solid rgba(201,165,92,.5);">${t('friend.pending')}</span>
            <button onclick="cancelFriendRequest('${escHtml(u.uid)}')" class="btn btn-ghost" style="padding:5px 9px;font-size:10.5px;border-color:rgba(var(--rose-rgb),.5);color:var(--bad-ink);">${t('friend.cancel')}</button>
          </div>`;
      } else if (isSending) {
        actionHtml = `<button disabled class="btn btn-primary" style="padding:6px 10px;font-size:11px;flex-shrink:0;opacity:.55;cursor:wait;">${t('friend.sending')}</button>`;
      } else {
        actionHtml = `<button onclick="sendFriendRequest('${escHtml(u.uid)}','${escHtml(u.name||'').replace(/'/g,'&#39;')}')" class="btn btn-primary" style="padding:6px 10px;font-size:11px;flex-shrink:0;">${t('friend.add')}</button>`;
      }
      return `
        <div style="display:flex;align-items:center;gap:10px;padding:8px 4px;">
          ${avatar}
          <div style="flex:1;min-width:0;">
            <div style="font-weight:600;color:var(--berry);font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(u.name || t('friend.noName'))} ${u.isAdmin ? '<span class="chip chip-coral" style="font-size:9px;padding:1px 6px;">🎓</span>' : ''}</div>
            <div style="font-size:10.5px;color:var(--soft);">${escHtml(u.email || '')}</div>
          </div>
          ${actionHtml}
        </div>`;
    }).join('');
  }

  function isLoggedInForChat() {
    const u = Store.get('user');
    return !!(u && !u.guest);
  }

  // ── Chat as full page (no modal) ──
  let _chatBuddyListenerOff = null;
  let _chatStatusTick = null;
  let _chatBuddyLastSeen = 0;
  const ONLINE_WINDOW_MS = 90 * 1000; // 90s — within this lastSeen window = "в сети"

  function chatStatusHtml(lastSeen) {
    if (!lastSeen) return `<span>—</span>`;
    const diff = Date.now() - lastSeen;
    if (diff < ONLINE_WINDOW_MS) {
      return `<span class="chat-online-dot"></span><span>${t('chat.online')}</span>`;
    }
    return `<span>${t('chat.lastSeen', { time: relativeTime(lastSeen) })}</span>`;
  }

  function paintChatHeaderStatus() {
    const slot = document.getElementById('chat-buddy-status');
    if (!slot) return;
    const now = Date.now();
    if (_chatIsGroup) {
      // Group: "Имя печатает…" beats the member count line.
      const me = myUid();
      const typing = Object.entries(_chatTyping || {})
        .filter(([uid, ts]) => uid !== me && now - Number(ts) < 6000);
      if (typing.length) {
        const nm = (_chatMembers && _chatMembers[typing[0][0]]) || t('chat.someone');
        slot.innerHTML = `<span class="chat-typing">${escHtml(nm)} ${t('chat.typing')}<span class="chat-typing-dots"><i></i><i></i><i></i></span></span>`;
        slot.classList.add('online');
        return;
      }
      const n = Object.keys(_chatMembers || {}).length;
      const memLabel = n ? (APP_LANG === 'ru' ? `${n} ${pluralRu(n, 'участник', 'участника', 'участников')}` : t('chat.members', { n })) : t('chat.group');
      slot.innerHTML = `<span>${memLabel}</span>`;
      slot.classList.remove('online');
      return;
    }
    // Typing takes priority over the online/last-seen line.
    const typingTs = _chatOtherUid && _chatTyping && Number(_chatTyping[_chatOtherUid]);
    if (typingTs && (now - typingTs < 6000)) {
      slot.innerHTML = `<span class="chat-typing">${t('chat.typing')}<span class="chat-typing-dots"><i></i><i></i><i></i></span></span>`;
      slot.classList.add('online');
      return;
    }
    slot.innerHTML = chatStatusHtml(_chatBuddyLastSeen);
    const isOnline = _chatBuddyLastSeen && (now - _chatBuddyLastSeen) < ONLINE_WINDOW_MS;
    slot.classList.toggle('online', !!isOnline);
  }

  function paintChatHeaderAvatar(avatar, name) {
    const av = document.getElementById('chat-buddy-avatar');
    if (!av) return;
    if (avatar) {
      av.style.background = `url(${avatar}) center/cover no-repeat`;
      av.textContent = '';
      av.classList.add('photo-zoom');
      av.dataset.photoSrc = avatar;
    } else {
      av.style.background = '';
      av.textContent = (name || '?').charAt(0).toUpperCase();
      av.classList.remove('photo-zoom');
      delete av.dataset.photoSrc;
    }
  }

  function attachChatBuddyListener(uid) {
    detachChatBuddyListener();
    if (typeof _db === 'undefined') return;
    const ref = _db.ref(`users/${uid}`);
    const handler = snap => {
      const u = snap.val() || {};
      _chatBuddyLastSeen = u.lastSeen || 0;
      paintChatHeaderAvatar(u.avatar, u.name);
      paintChatHeaderStatus();
    };
    ref.on('value', handler);
    _chatBuddyListenerOff = () => ref.off('value', handler);
    // Keep "X min ago" fresh while the chat is open
    _chatStatusTick = setInterval(paintChatHeaderStatus, 30000);
  }

  function detachChatBuddyListener() {
    if (_chatBuddyListenerOff) { try { _chatBuddyListenerOff(); } catch(_){} _chatBuddyListenerOff = null; }
    if (_chatStatusTick) { clearInterval(_chatStatusTick); _chatStatusTick = null; }
    _chatBuddyLastSeen = 0;
  }

  function openChat(otherUid, otherName) {
    if (!isLoggedInForChat()) { toast(t('ui.102')); return; }
    _openConversation({ isGroup: false, key: otherUid, chatId: chatIdFor(myUid(), otherUid), title: otherName });
  }

  function openGroupChat(gid, title) {
    if (!isLoggedInForChat()) { toast(t('ui.102')); return; }
    const gtitle = title || (_groupsCache && _groupsCache[gid] && _groupsCache[gid].title) || t('grp.defTitle');
    _openConversation({ isGroup: true, key: gid, chatId: gid, title: gtitle });
  }

  function pluralRu(n, one, few, many) {
    const m100 = n % 100, m10 = n % 10;
    if (m100 >= 11 && m100 <= 14) return many;
    if (m10 === 1) return one;
    if (m10 >= 2 && m10 <= 4) return few;
    return many;
  }

  function _openConversation(opts) {
    const isGroup = !!opts.isGroup;
    const key = opts.key;            // friend uid (DM) or gid (group) — also the unreadFrom key
    const chatId = opts.chatId;
    const title = opts.title || '';
    _chatCurrentId = chatId;
    _chatOtherUid = key;
    _chatIsGroup = isGroup;
    _chatMembers = {};               // uid -> name (groups: typing line + sender labels)
    _chatReplyTo = null;
    _chatReadMeta = {};
    _lastChatMsgs = {};
    _chatSeenKeys = null; _chatPrevReactions = {}; _chatTyping = {}; _chatLastRenderedSig = null; // reset FX so history doesn't animate
    bumpChatActivity(key); // opening a chat surfaces it to the top of the list
    document.getElementById(_popupId(key))?.remove(); // clear any pending banner for this chat
    // Remove existing if any
    document.getElementById('chat-page')?.remove();
    document.getElementById('chat-backdrop')?.remove();
    // Подложка: на ПК/планшете чат — карточка с воздухом по краям,
    // клик мимо окна закрывает переписку (на телефоне чат во весь экран).
    const backdrop = document.createElement('div');
    backdrop.id = 'chat-backdrop';
    backdrop.className = 'chat-backdrop';
    backdrop.addEventListener('click', closeChat);
    document.body.appendChild(backdrop);
    const m = document.createElement('div');
    m.className = 'chat-page';
    m.id = 'chat-page';
    const showRemoveBtn = !isGroup && !isAdmin();
    // Seed from cache so header doesn't flash empty before Firebase responds
    const cached = (!isGroup && _usersDirCache && _usersDirCache[key]) || {};
    const buddyIsAdmin = !isGroup && !!(cached && cached.isAdmin); // чат с Мади → кнопка Telegram
    const initialAvatar = cached.avatar || '';
    const initialLastSeen = cached.lastSeen || 0;
    _chatBuddyLastSeen = initialLastSeen;
    const avatarStyle = (initialAvatar && !isGroup)
      ? `background:url(${initialAvatar}) center/cover no-repeat;`
      : '';
    const avatarContent = isGroup
      ? '<i class="fa-solid fa-user-group" style="font-size:13px;"></i>'
      : (initialAvatar ? '' : escHtml((title || '?').charAt(0).toUpperCase()));
    const avatarClass = 'chat-buddy-avatar' + ((initialAvatar && !isGroup) ? ' photo-zoom' : '') + (isGroup ? ' chat-group-av' : '');
    const avatarData = (initialAvatar && !isGroup) ? `data-photo-src="${initialAvatar}"` : '';
    const statusInitial = isGroup ? '<span>' + t('ui.103') + '</span>' : chatStatusHtml(initialLastSeen);
    m.innerHTML = `
      <div class="chat-sheet">
        <div class="chat-header">
          <button id="chat-close-btn" class="chat-back-btn" aria-label="${t('ui.053')}"><i class="fa-solid fa-arrow-left"></i></button>
          <div class="chat-buddy-info">
            <div class="chat-buddy-name">${escHtml(title)}</div>
            <div id="chat-buddy-status" class="chat-buddy-status">${statusInitial}</div>
          </div>
          ${buddyIsAdmin ? `<a href="${KM_TELEGRAM_URL}" target="_blank" rel="noopener" class="chat-mini-btn chat-tg-btn" aria-label="Telegram" title="Telegram Мади"><i class="fa-brands fa-telegram"></i></a>` : ''}
          ${isGroup ? '<button id="chat-group-menu-btn" class="chat-mini-btn chat-mini-neutral" aria-label="' + t('ui.104') + '" title="' + t('ui.104') + '"><i class="fa-solid fa-ellipsis"></i></button>' : ''}
          ${showRemoveBtn ? '<button id="chat-remove-friend-btn" class="chat-mini-btn" aria-label="' + t('ui.105') + '" title="' + t('ui.105') + '"><i class="fa-solid fa-user-xmark"></i></button>' : ''}
          <div id="chat-buddy-avatar" class="${avatarClass}" ${avatarData} style="${avatarStyle}">${avatarContent}</div>
        </div>
        <div class="chat-body" id="chat-body">
          <div style="text-align:center;padding:24px;color:var(--soft);font-size:12px;">${t('ui.106')}</div>
        </div>
        <button type="button" id="chat-scroll-fab" class="chat-scroll-fab" aria-label="${t('ui.107')}"><i class="fa-solid fa-chevron-down"></i></button>
        <div id="chat-reply-preview" class="chat-reply-preview" style="display:none;"></div>
        <div id="chat-emoji-panel" class="chat-emoji-panel" style="display:none;"></div>
        <form class="chat-input-row" id="chat-form">
          <button type="button" id="chat-emoji-btn" class="chat-emoji-btn" aria-label="${t('ui.108')}" onclick="toggleEmojiPicker()"><i class="fa-regular fa-face-smile"></i></button>
          <input id="chat-input" class="chat-input" placeholder="${t('ui.109')}" aria-label="${t('ui.110')}" autocomplete="off" maxlength="2000">
          <button type="submit" id="chat-send-btn" class="chat-send-btn" aria-label="${t('ui.111')}"><i class="fa-solid fa-paper-plane"></i></button>
        </form>
      </div>`;
    document.body.appendChild(m);
    document.body.classList.add('chat-open');
    // Apply online class to seeded status
    paintChatHeaderStatus();
    // DM: live avatar + lastSeen. Group: load member names for the status line.
    if (!isGroup) attachChatBuddyListener(key);
    else loadGroupMembers(chatId);

    // Event listeners (avoid inline onclick — safer with names containing apostrophes etc.)
    document.getElementById('chat-close-btn').addEventListener('click', closeChat);
    // DM: тап по имени/статусу открывает профиль собеседника (Telegram-style).
    if (!isGroup) {
      const info = m.querySelector('.chat-buddy-info');
      if (info) {
        info.classList.add('chat-buddy-info-tap');
        info.addEventListener('click', () => openUserProfile(key));
      }
    }
    if (showRemoveBtn) {
      document.getElementById('chat-remove-friend-btn').addEventListener('click', () => removeFriend(key));
    }
    if (isGroup) {
      document.getElementById('chat-group-menu-btn').addEventListener('click', () => openGroupMenu(chatId, title));
    }
    const form = document.getElementById('chat-form');
    const inp  = document.getElementById('chat-input');
    const btn  = document.getElementById('chat-send-btn');
    // Keep the mobile keyboard open: buttons must never steal focus from the input.
    const keepFocus = e => e.preventDefault();
    btn.addEventListener('pointerdown', keepFocus);
    document.getElementById('chat-emoji-btn').addEventListener('pointerdown', keepFocus);
    document.getElementById('chat-emoji-panel').addEventListener('pointerdown', keepFocus);
    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const text = (inp.value || '').trim();
      if (!text) return;
      const replyTo = _chatReplyTo;
      inp.value = '';
      _chatReplyTo = null;
      renderReplyPreview();
      closeEmojiPanel();  // Telegram-style: панель эмодзи закрывается после отправки
      stopTyping();       // I just sent → clear my "печатает…" flag
      inp.focus();        // keyboard stays up
      btn.disabled = true;
      try {
        if (isGroup) await sendGroupMessage(chatId, text, replyTo);
        else await sendChatMessage(key, title, text, replyTo);
      } catch (err) {
        console.error('chat send error', err);
        toast(t('ui.112') + (err.message || err.code || 'ошибка'));
        inp.value = text; // restore so user can retry
        _chatReplyTo = replyTo; renderReplyPreview();
      } finally {
        btn.disabled = false;
        if (document.activeElement !== inp) inp.focus();
      }
    });
    inp.addEventListener('input', signalTyping); // broadcast "печатает…" to the other side
    const body = document.getElementById('chat-body');
    attachChatGestures(body);
    // Scroll-to-bottom FAB (Telegram): appears once you scroll up to read history.
    const fab = document.getElementById('chat-scroll-fab');
    body.addEventListener('scroll', () => {
      const away = body.scrollHeight - body.scrollTop - body.clientHeight;
      fab.classList.toggle('show', away > 280);
    }, { passive: true });
    fab.addEventListener('click', () => { body.scrollTo({ top: body.scrollHeight, behavior: 'smooth' }); });
    setTimeout(() => inp.focus(), 100);
    attachChatListener(chatId, key);
    markChatRead(key, chatId);
  }

  let _chatGroupMeta = null;
  async function loadGroupMembers(gid) {
    if (typeof _db === 'undefined') return;
    try {
      if (!_usersDirCache) await loadUsersDirectory();
      const snap = await _db.ref(`chats/${gid}/meta`).once('value');
      const meta = snap.val() || {};
      _chatGroupMeta = meta;
      const members = meta.members || {};
      const names = {};
      Object.keys(members).forEach(uid => {
        const d = (_usersDirCache && _usersDirCache[uid]) || {};
        names[uid] = d.name || (_friendsCache && _friendsCache[uid] && _friendsCache[uid].name) || t('grp.defMember');
      });
      _chatMembers = names;
      // Фото группы в шапку (если задано)
      if (meta.photo) {
        const av = document.getElementById('chat-buddy-avatar');
        if (av) { av.style.background = `url(${meta.photo}) center/cover no-repeat`; av.innerHTML = ''; av.classList.remove('chat-group-av'); }
      }
      paintChatHeaderStatus();
    } catch (_) {}
  }

  function openGroupMenu(gid, title) {
    // Чат сообщества общий и постоянный — из него нельзя выйти или удалить его
    if (gid === COMMUNITY_GID) { toast(t('comm.permanent'), 'var(--sage)'); return; }
    const me = myUid();
    const names = Object.entries(_chatMembers || {});
    const meta = _chatGroupMeta || {};
    const photo = meta.photo;
    const headAv = photo
      ? `<div class="chat-row-av" style="width:64px;height:64px;background:url(${photo}) center/cover no-repeat;margin:0 auto;"></div>`
      : `<div class="chat-row-av chat-group-av" style="width:64px;height:64px;font-size:24px;margin:0 auto;"><i class="fa-solid fa-user-group"></i></div>`;
    const sheet = document.createElement('div');
    sheet.className = 'modal-bg';
    sheet.onclick = e => { if (e.target === sheet) sheet.remove(); };
    sheet.innerHTML = `
      <div class="modal-sheet" style="border-radius:24px 24px 0 0; padding:18px 16px calc(20px + env(safe-area-inset-bottom,0px));">
        <div style="text-align:center;margin-bottom:10px;">
          ${headAv}
          <div class="display" style="font-size:20px;color:var(--berry);margin-top:8px;">${escHtml(title)}</div>
          ${meta.desc ? `<div style="font-size:12.5px;color:var(--soft);margin-top:4px;line-height:1.5;">${escHtml(meta.desc)}</div>` : ''}
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin:0 2px 8px;">
          <span style="font-size:10px;letter-spacing:.18em;color:var(--soft);">${t('ui.t011')} · ${names.length}</span>
          <button class="chip chip-coral" style="font-size:10px;padding:4px 10px;cursor:pointer;border:none;" onclick="openAddGroupMember('${escHtml(gid)}')"><i class="fa-solid fa-user-plus" style="font-size:9px;"></i> ${t('ui.090')}</button>
        </div>
        <div style="display:grid;gap:6px;max-height:240px;overflow-y:auto;">
          ${names.map(([uid, nm]) => `
            <div style="display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:12px;background:var(--paper);">
              <div class="chat-row-av chat-row-av-initial" style="width:34px;height:34px;font-size:13px;">${escHtml((nm || '?').charAt(0).toUpperCase())}</div>
              <span style="flex:1;font-size:13px;font-weight:600;color:var(--berry);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escHtml(nm)}${uid === me ? ' <span style="font-size:10px;color:var(--coral);">· это ты</span>' : (uid === meta.owner ? ' <span style="font-size:10px;color:var(--gold-ink);">· создатель</span>' : '')}</span>
            </div>`).join('')}
        </div>
        <button class="btn btn-ghost btn-block" style="margin-top:14px; color:var(--bad-ink); border-color:rgba(179,58,74,.25);" onclick="leaveGroupChat('${escHtml(gid)}'); this.closest('.modal-bg').remove();"><i class="fa-solid fa-right-from-bracket"></i> ${t('ui.113')}</button>
      </div>`;
    document.body.appendChild(sheet);
  }

  // Добавить участника в группу (из друзей / всех учеников у админа) + системное сообщение
  function openAddGroupMember(gid) {
    const me = myUid();
    let pool;
    if (isAdmin()) {
      const dir = _usersDirCache || {};
      pool = {}; Object.keys(dir).forEach(uid => { if (uid !== me && !(dir[uid] && dir[uid].isAdmin)) pool[uid] = { name: dir[uid].name || t('feed.studentName') }; });
    } else pool = _friendsCache || {};
    const current = _chatMembers || {};
    const candidates = Object.keys(pool).filter(uid => !current[uid]);
    if (!candidates.length) { toast(t('ui.114')); return; }
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center'; m.id = 'add-gm-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:340px;">
        <div class="page-eyebrow">${t('ui.115')}</div>
        <div class="display" style="font-size:18px;color:var(--berry);margin:2px 0 12px;">${t('ui.116')}</div>
        <div style="display:grid;gap:6px;max-height:300px;overflow-y:auto;">
          ${candidates.map(uid => {
            const nm = (pool[uid] && pool[uid].name) || (_usersDirCache && _usersDirCache[uid] && _usersDirCache[uid].name) || t('grp.defMember');
            return `<button type="button" class="cw-lobby-card" style="padding:9px 12px;" onclick="addGroupMember('${escHtml(gid)}','${escHtml(uid)}','${escHtml(nm).replace(/'/g,'&#39;')}')">
              <div class="chat-row-av chat-row-av-initial" style="width:34px;height:34px;font-size:13px;">${escHtml(nm.charAt(0).toUpperCase())}</div>
              <span style="flex:1;font-size:13px;font-weight:600;color:var(--berry);text-align:left;">${escHtml(nm)}</span>
              <i class="fa-solid fa-plus" style="color:var(--coral);font-size:12px;"></i>
            </button>`;
          }).join('')}
        </div>
      </div>`;
    document.body.appendChild(m);
  }
  async function addGroupMember(gid, uid, nm) {
    if (typeof _db === 'undefined') return;
    const now = Date.now();
    const title = (_chatGroupMeta && _chatGroupMeta.title) || (_groupsCache[gid] && _groupsCache[gid].title) || t('grp.defTitle');
    const updates = {};
    updates[`chats/${gid}/meta/members/${uid}`] = true;
    updates[`users/${uid}/groups/${gid}`] = { title, since: now };
    const sysKey = _db.ref(`chats/${gid}/messages`).push().key;
    updates[`chats/${gid}/messages/${sysKey}`] = { type: 'system', text: t('ui.r036',{name: nm}), at: now };
    updates[`chats/${gid}/meta/lastAt`] = now;
    try {
      await _db.ref().update(updates);
      document.getElementById('add-gm-modal')?.remove();
      document.querySelector('.modal-sheet')?.closest('.modal-bg')?.remove();
      toast(t('ui.117',{name: nm}), 'var(--sage)');
      loadGroupMembers(gid);
    } catch (e) { console.warn(e); toast(t('ui.118')); }
  }

  async function leaveGroupChat(gid) {
    if (!confirm(t('ui.119'))) return;
    const me = myUid();
    if (typeof _db === 'undefined') return;
    const now = Date.now();
    const updates = {};
    updates[`chats/${gid}/meta/members/${me}`] = null;
    updates[`users/${me}/groups/${gid}`] = null;
    updates[`users/${me}/unreadFrom/${gid}`] = null;
    // Системное сообщение о выходе
    const sysKey = _db.ref(`chats/${gid}/messages`).push().key;
    updates[`chats/${gid}/messages/${sysKey}`] = { type: 'system', text: t('ui.r037',{name: myName()}), at: now };
    updates[`chats/${gid}/meta/lastAt`] = now;
    try {
      await _db.ref().update(updates);
      closeChat();
      toast(t('ui.120'));
    } catch (e) { console.warn(e); toast(t('ui.121')); }
  }

  function closeChat() {
    stopTyping(); // clear my typing flag before tearing down
    // Выход из чата сообщества = «прочитано до этого момента» (значок new гаснет)
    if (_chatCurrentId === COMMUNITY_GID) { _markCommunityRead(); updateChatBadges(); }
    detachChatListener();
    detachChatBuddyListener();
    _chatCurrentId = null;
    _chatOtherUid = null;
    _chatIsGroup = false;
    _chatMembers = {};
    _chatGroupMeta = null;
    _chatReplyTo = null;
    document.getElementById('chat-page')?.remove();
    document.getElementById('chat-backdrop')?.remove();
    document.getElementById('chat-modal')?.remove();
    document.body.classList.remove('chat-open');
    // Снимаем фокус, чтобы строка чата не оставалась с залипшей рамкой-обводкой
    try { document.activeElement?.blur(); } catch (_) {}
    renderFriendsAndChat(); // refresh previews/ordering after the conversation
  }

  // ════════════════ ПРОФИЛЬ ЧЕЛОВЕКА (стиль Telegram Premium) ════════════════
  // Открывается тапом по имени/аватару в шапке чата (и по своему профилю).
  // Сверху — фон-обложка, поверх — аватар, ниже — имя, статус, уровень, «о себе».
  function _userProfileHtml(o) {
    const name = escHtml(o.name || t('nav.profile'));
    const initial = escHtml((o.name || '?').charAt(0).toUpperCase());
    const coverStyle = o.cover ? `background-image:url(${o.cover});` : '';
    const avInner = o.avatar
      ? `<div class="up-avatar-img photo-zoom" data-photo-src="${o.avatar}" style="background:url(${o.avatar}) center/cover no-repeat;"></div>`
      : `<div class="up-avatar-initial">${initial}</div>`;
    const online = o.lastSeen && (Date.now() - o.lastSeen) < ONLINE_WINDOW_MS;
    const status = o.isMe ? t('up.itsYou')
      : online ? `<span class="chat-online-dot"></span> ${t('chat.online')}`
      : (o.lastSeen ? t('chat.lastSeen', { time: relativeTime(o.lastSeen) }) : t('chat.offline'));
    // Уровень / ранг / стрик
    let chips = '';
    if (o.stats) {
      const lvl = getLevel(o.stats.xp || 0);
      const rank = getRank(lvl, o.gender);
      const streak = o.stats.streak || 0;
      const words = (o.stats.wordsLearned && o.stats.wordsLearned.length) || o.stats.words || 0;
      const streakSub = APP_LANG === 'ru' ? `${pluralDays(streak)} ${t('ui.r038')}` : t('up.daysInRow');
      chips = `<div class="up-chips">
        <div class="up-chip"><span class="up-chip-ico">${rank.emoji}</span><span><b>${lvl}</b> ${t('up.level')}<br><span class="up-chip-sub">${escHtml(rank.label)}</span></span></div>
        <div class="up-chip"><span class="up-chip-ico">🔥</span><span><b>${streak}</b><br><span class="up-chip-sub">${streakSub}</span></span></div>
        <div class="up-chip"><span class="up-chip-ico">📚</span><span><b>${words}</b><br><span class="up-chip-sub">${t('up.wordsLearned')}</span></span></div>
      </div>`;
    }
    const adminBadge = o.isAdmin ? ` <span class="chip chip-coral" style="font-size:10px;padding:2px 8px;vertical-align:middle;">${t('up.teacher')}</span>` : '';
    const bioBlock = o.bio
      ? `<div class="up-section"><div class="up-section-label">${t('up.about')}</div><div class="up-bio">${escHtml(o.bio)}</div></div>`
      : (o.isMe ? `<div class="up-section"><div class="up-section-label">${t('up.about')}</div><div class="up-bio up-bio-empty" onclick="closeUserProfile(); showEditProfile();">${t('up.bioEmpty')}</div></div>` : '');
    const joinLine = o.joinedAt ? `<div class="up-join">${t('up.withUsSince', { date: _fmtJoinDate(o.joinedAt) })}</div>` : '';
    const action = o.isMe
      ? `<button class="up-action up-action-ghost" onclick="closeUserProfile(); showEditProfile();"><i class="fa-solid fa-pen"></i> ${t('set.editProfile')}</button>`
      : `<button class="up-action up-action-primary" onclick="_profileToChat('${escHtml(o.uid)}','${name.replace(/'/g,"&#39;")}')"><i class="fa-solid fa-paper-plane"></i> ${t('up.writeMsg')}</button>`;
    const editCover = o.isMe
      ? `<button class="up-cover-edit" onclick="closeUserProfile(); showEditProfile();" aria-label="${t('up.changeCover')}" title="${t('up.changeCover')}"><i class="fa-solid fa-camera"></i></button>`
      : '';
    return `
      <div class="up-cover${o.cover ? ' has-photo' : ''}" style="${coverStyle}">
        <button class="up-back" onclick="closeUserProfile()" aria-label="${t('ui.053')}"><i class="fa-solid fa-arrow-left"></i></button>
        ${editCover}
      </div>
      <div class="up-body">
        <div class="up-avatar">${avInner}${online ? '<span class="up-online-dot"></span>' : ''}</div>
        <div class="up-name">${name}${adminBadge}</div>
        <div class="up-status${online ? ' online' : ''}">${status}</div>
        ${chips}
        ${bioBlock}
        ${joinLine}
        <div class="up-actions">${action}</div>
      </div>`;
  }
  function _fmtJoinDate(ts) {
    const d = new Date(ts);
    if ((typeof APP_LANG === 'undefined') || APP_LANG === 'ru') return `${d.getDate()} ${monthsRu[d.getMonth()].toLowerCase()} ${d.getFullYear()}`;
    return d.toLocaleDateString(APP_LANG === 'uz' ? 'uz-Latn' : 'en', { day: 'numeric', month: 'long', year: 'numeric' });
  }
  function openUserProfile(uid) {
    if (!uid) return;
    const isMe = uid === myUid();
    document.getElementById('user-profile-page')?.remove();
    const dir = (_usersDirCache && _usersDirCache[uid]) || {};
    // Для себя — берём свежие локальные данные (имя/аватар/обложка/био/статистика)
    const seed = isMe
      ? { uid, isMe: true, name: (Store.get('user') || {}).name || dir.name, avatar: UStore.get('avatar') || dir.avatar,
          cover: UStore.get('cover') || dir.cover, bio: UStore.get('bio') || dir.bio,
          lastSeen: Date.now(), isAdmin: isAdmin(), stats, gender: userGender(), joinedAt: stats.firstOpenTs || dir.joinedAt }
      : { uid, isMe: false, name: dir.name, avatar: dir.avatar, cover: dir.cover, bio: dir.bio,
          lastSeen: dir.lastSeen, isAdmin: dir.isAdmin, stats: dir.stats, gender: dir.gender, joinedAt: dir.joinedAt };
    const m = document.createElement('div');
    m.className = 'user-profile-page';
    m.id = 'user-profile-page';
    m.innerHTML = _userProfileHtml(seed);
    document.body.appendChild(m);
    document.body.classList.add('chat-open');
    tagInteractive(m);
    // Подтягиваем свежий снимок (био/обложка могли обновиться на другом устройстве)
    if (!isMe && typeof _db !== 'undefined') {
      _db.ref('users/' + uid).once('value').then(snap => {
        const u = snap.val(); if (!u) return;
        const cur = document.getElementById('user-profile-page');
        if (!cur) return;
        cur.innerHTML = _userProfileHtml({ uid, isMe: false, name: u.name, avatar: u.avatar, cover: u.cover,
          bio: u.bio, lastSeen: u.lastSeen, isAdmin: u.isAdmin, stats: u.stats, gender: u.gender, joinedAt: u.joinedAt });
        tagInteractive(cur);
      }).catch(() => {});
    }
  }
  function closeUserProfile() {
    document.getElementById('user-profile-page')?.remove();
    // Снимаем chat-open только если под профилем нет открытого чата/игры.
    if (!document.querySelector('.chat-page') && !document.querySelector('.game-page')) {
      document.body.classList.remove('chat-open');
    }
  }
  function _profileToChat(uid, name) {
    closeUserProfile();
    // Если мы уже в этом чате (профиль открыли из шапки) — просто вернуться в него.
    if (_chatCurrentId && _chatCurrentId === chatIdFor(myUid(), uid)) return;
    openChat(uid, name);
  }

  // ── Chat message interactions: swipe-to-reply (Telegram-style), double-tap ❤️,
  //    long-press menu, reactions. All bound on the container via delegation so they
  //    survive the innerHTML re-render on every new message. ────────────────────────
  function attachChatGestures(bodyEl) {
    if (!bodyEl || bodyEl._gesturesBound) return;
    bodyEl._gesturesBound = true;
    let lpTimer = null, lpFired = false, lastMid = null, lastAt = 0, startX = 0, startY = 0;
    // swipe-to-reply state
    let swBubble = null, swMid = null, swDir = null, swPull = 0, swArmed = false;
    const SW_THRESHOLD = 56, SW_MAX = 84;
    const clearLp = () => { if (lpTimer) { clearTimeout(lpTimer); lpTimer = null; } };
    const bubbleOf = e => (e.target.closest ? e.target.closest('.chat-bubble[data-mid]') : null);
    const onChip = e => !!(e.target.closest && e.target.closest('.chat-react-chip'));

    const swipeArrow = () => {
      let a = document.getElementById('chat-swipe-arrow');
      if (!a) {
        a = document.createElement('div');
        a.id = 'chat-swipe-arrow';
        a.className = 'chat-swipe-arrow';
        a.innerHTML = '<i class="fa-solid fa-reply"></i>';
        document.body.appendChild(a);
      }
      return a;
    };
    const positionArrow = () => {
      if (!swBubble) return;
      const r = swBubble.getBoundingClientRect();
      const a = swipeArrow();
      const f = Math.min(1, swPull / SW_THRESHOLD);
      a.style.top = (r.top + r.height / 2) + 'px';
      a.style.left = Math.max(16, r.left - 34) + 'px';
      a.style.opacity = String(Math.max(0, f));
      a.style.transform = 'translate(-50%,-50%) scale(' + (0.5 + 0.5 * f) + ')';
      a.classList.toggle('armed', swArmed);
    };
    const hideArrow = () => {
      const a = document.getElementById('chat-swipe-arrow');
      if (a) { a.style.opacity = '0'; a.classList.remove('armed'); }
    };
    const resetSwipe = animate => {
      if (swBubble) {
        swBubble.style.transition = animate ? 'transform .18s ease' : '';
        swBubble.style.transform = '';
      }
      hideArrow();
      swBubble = null; swMid = null; swDir = null; swPull = 0; swArmed = false;
    };

    bodyEl.addEventListener('pointerdown', e => {
      if (onChip(e)) return;
      const b = bubbleOf(e); if (!b) return;
      lpFired = false; startX = e.clientX; startY = e.clientY;
      swBubble = b; swMid = b.dataset.mid; swDir = null; swPull = 0; swArmed = false;
      lpTimer = setTimeout(() => { lpFired = true; resetSwipe(true); openMsgMenu(b.dataset.mid); }, 480);
    });

    bodyEl.addEventListener('pointermove', e => {
      const dx = e.clientX - startX, dy = e.clientY - startY;
      if (lpTimer && (Math.abs(dx) > 10 || Math.abs(dy) > 10)) clearLp();
      if (!swBubble) return;
      if (swDir === null) {
        if (Math.abs(dx) < 8 && Math.abs(dy) < 8) return;
        if (dx > 0 && Math.abs(dx) > Math.abs(dy)) {
          swDir = 'h';
          swBubble.style.transition = 'none';
        } else {
          swDir = 'v'; swBubble = null; // vertical → native scroll, abandon swipe
          return;
        }
      }
      if (swDir === 'h') {
        if (e.cancelable) e.preventDefault();
        let p = dx;
        if (p > SW_THRESHOLD) p = SW_THRESHOLD + (p - SW_THRESHOLD) * 0.35; // rubber-band past threshold
        swPull = Math.max(0, Math.min(p, SW_MAX));
        swBubble.style.transform = 'translateX(' + swPull + 'px)';
        const armedNow = swPull >= SW_THRESHOLD;
        if (armedNow && !swArmed && navigator.vibrate) { try { navigator.vibrate(12); } catch (_) {} }
        swArmed = armedNow;
        positionArrow();
      }
    });

    bodyEl.addEventListener('pointerup', e => {
      clearLp();
      const dir = swDir;
      if (dir === 'h') {
        const fire = swArmed, mid = swMid;
        resetSwipe(true);
        if (fire && mid) startReply(mid);
        return; // a swipe is not also a tap
      }
      resetSwipe(false);
      if (dir === 'v') return;            // was a scroll, ignore
      if (lpFired || onChip(e)) return;
      const b = bubbleOf(e); if (!b) return;
      const mid = b.dataset.mid, now = Date.now();
      if (lastMid === mid && now - lastAt < 320) { lastMid = null; lastAt = 0; quickReact(mid); }
      else { lastMid = mid; lastAt = now; }
    });

    bodyEl.addEventListener('pointercancel', () => { clearLp(); resetSwipe(true); });
    bodyEl.addEventListener('contextmenu', e => {
      const b = bubbleOf(e); if (b) { e.preventDefault(); openMsgMenu(b.dataset.mid); }
    });
  }

  const CHAT_REACTIONS = ['❤️','😂','😮','😢','👍','🔥'];
  function openMsgMenu(mid) {
    const m = _lastChatMsgs[mid]; if (!m) return;
    const me = myUid();
    const mine = m.from === me;
    const myReact = (m.reactions && m.reactions[me]) || '';
    const sheet = document.createElement('div');
    sheet.className = 'modal-bg';
    sheet.onclick = e => { if (e.target === sheet) sheet.remove(); };
    sheet.innerHTML = `
      <div class="modal-sheet" style="border-radius:24px 24px 0 0; padding:16px 16px calc(20px + env(safe-area-inset-bottom,0px));">
        <div class="msg-react-row">
          ${CHAT_REACTIONS.map(em => `<button class="msg-react-btn ${myReact === em ? 'active' : ''}" onclick="reactMessage('${mid}','${em}'); this.closest('.modal-bg').remove();">${em}</button>`).join('')}
        </div>
        <div class="msg-menu-quote"><b>${escHtml(m.fromName || '')}</b><br>${escHtml((m.text || '').slice(0, 140))}</div>
        <button class="btn btn-ghost btn-block" style="margin-top:10px;" onclick="startReply('${mid}'); this.closest('.modal-bg').remove();"><i class="fa-solid fa-reply"></i> ${t('ui.122')}</button>
        <button class="btn btn-ghost btn-block" style="margin-top:8px;" onclick="copyChatMessage('${mid}'); this.closest('.modal-bg').remove();"><i class="fa-solid fa-copy"></i> ${t('chat.copy')}</button>
        <button class="btn btn-ghost btn-block" style="margin-top:8px;" onclick="forwardChatMessage('${mid}'); this.closest('.modal-bg').remove();"><i class="fa-solid fa-share"></i> ${t('chat.forward')}</button>
        ${mine ? `<button class="btn btn-ghost btn-block" style="margin-top:8px; color:var(--bad-ink); border-color:rgba(179,58,74,.25);" onclick="deleteChatMessage('${mid}'); this.closest('.modal-bg').remove();"><i class="fa-solid fa-trash"></i> ${t('ui.018')}</button>` : ''}
      </div>`;
    document.body.appendChild(sheet);
  }

  async function reactMessage(mid, emoji) {
    const m = _lastChatMsgs[mid]; if (!m || typeof _db === 'undefined') return;
    const me = myUid(); const chatId = _chatCurrentId; if (!chatId) return;
    const cur = (m.reactions && m.reactions[me]) || '';
    const ref = _db.ref(`chats/${chatId}/messages/${mid}/reactions/${me}`);
    try { if (cur === emoji) await ref.remove(); else await ref.set(emoji); } catch (_) {}
  }
  function quickReact(mid) { reactMessage(mid, '❤️'); }

  // Копировать текст сообщения (clipboard API с фолбэком на execCommand для старых WebView).
  function copyChatMessage(mid) {
    const m = _lastChatMsgs[mid]; if (!m) return;
    const text = m.text || '';
    const done = () => toast(t('chat.copied'), 'var(--sage)');
    const fallback = () => {
      try {
        const ta = document.createElement('textarea');
        ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
        document.body.appendChild(ta); ta.focus(); ta.select();
        document.execCommand('copy'); ta.remove(); done();
      } catch (_) { toast(t('chat.copyFail')); }
    };
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done).catch(fallback);
      else fallback();
    } catch (_) { fallback(); }
  }

  // Переслать сообщение: лист выбора (сообщество + друзья), затем отправка с пометкой.
  let _forwardMid = null;
  function forwardChatMessage(mid) {
    const m = _lastChatMsgs[mid]; if (!m) return;
    _forwardMid = mid;
    const me = myUid();
    const rows = [`<button class="fwd-row" onclick="doForward('${COMMUNITY_GID}', true)"><span class="fwd-av" style="background:var(--grad-coral); color:#fff;">🌍</span><span class="fwd-name">${t('comm.title')}</span></button>`];
    Object.keys(_friendsCache || {}).forEach(uid => {
      if (uid === me) return;
      const dir = (_usersDirCache && _usersDirCache[uid]) || {};
      const name = dir.name || 'Друг';
      const av = dir.avatar
        ? `<span class="fwd-av" style="background:url(${dir.avatar}) center/cover no-repeat;"></span>`
        : `<span class="fwd-av">${escHtml(name.charAt(0).toUpperCase())}</span>`;
      rows.push(`<button class="fwd-row" onclick="doForward('${escHtml(uid)}', false)">${av}<span class="fwd-name">${escHtml(name)}</span></button>`);
    });
    const sheet = document.createElement('div');
    sheet.className = 'modal-bg';
    sheet.onclick = e => { if (e.target === sheet) sheet.remove(); };
    sheet.innerHTML = `
      <div class="modal-sheet" style="border-radius:24px 24px 0 0; padding:16px 16px calc(20px + env(safe-area-inset-bottom,0px)); max-height:70vh; overflow-y:auto;">
        <div class="fwd-title">${t('chat.forwardTo')}</div>
        <div class="fwd-list">${rows.join('')}${rows.length <= 1 ? `<div style="text-align:center; color:var(--soft); font-size:12px; padding:12px;">${t('chat.noFriends')}</div>` : ''}</div>
      </div>`;
    document.body.appendChild(sheet);
  }
  async function doForward(key, isGroup) {
    const m = _lastChatMsgs[_forwardMid];
    document.querySelectorAll('.modal-bg').forEach(x => x.remove());
    if (!m) return;
    const text = t('chat.fwdPrefix', { name: m.fromName || '' }) + '\n' + (m.text || '');
    try {
      if (isGroup) await sendGroupMessage(key, text);
      else {
        const dir = (_usersDirCache && _usersDirCache[key]) || {};
        await sendChatMessage(key, dir.name || 'Друг', text);
      }
      toast(t('chat.forwarded'), 'var(--sage)');
    } catch (_) { toast(t('ui.126')); }
  }

  function startReply(mid) {
    const m = _lastChatMsgs[mid]; if (!m) return;
    _chatReplyTo = { id: mid, text: (m.text || '').slice(0, 200), from: m.from, fromName: m.fromName || '' };
    renderReplyPreview();
    document.getElementById('chat-input')?.focus();
  }
  function cancelReply() { _chatReplyTo = null; renderReplyPreview(); }
  function renderReplyPreview() {
    const bar = document.getElementById('chat-reply-preview');
    if (!bar) return;
    if (!_chatReplyTo) { bar.style.display = 'none'; bar.innerHTML = ''; return; }
    bar.style.display = 'flex';
    bar.innerHTML = `
      <div class="crp-bar"></div>
      <div class="crp-body">
        <div class="crp-name"><i class="fa-solid fa-reply" style="font-size:10px;"></i> ${escHtml(_chatReplyTo.fromName || '')}</div>
        <div class="crp-text">${escHtml(_chatReplyTo.text)}</div>
      </div>
      <button class="crp-x" onclick="cancelReply()" aria-label="${t('ui.123')}">×</button>`;
  }

  async function deleteChatMessage(mid) {
    const m = _lastChatMsgs[mid]; if (!m) return;
    if (m.from !== myUid()) { toast(t('ui.124')); return; }
    const chatId = _chatCurrentId; if (!chatId || typeof _db === 'undefined') return;
    if (!confirm(t('ui.125'))) return;
    try { await _db.ref(`chats/${chatId}/messages/${mid}`).remove(); } catch (_) { toast(t('ui.126')); }
  }

  function detachChatListener() {
    if (_chatListenerOff) { try { _chatListenerOff(); } catch(_){} _chatListenerOff = null; }
  }

  function attachChatListener(chatId, otherUid) {
    detachChatListener();
    if (typeof _db === 'undefined') return;
    const mref = _db.ref(`chats/${chatId}/messages`).limitToLast(200);
    const mh = snap => {
      _lastChatMsgs = snap.val() || {};
      renderChatMessages(_lastChatMsgs);
      // New messages arrived while the chat is open → mark them read (clears unread, sets ✓✓).
      if (otherUid) markChatRead(otherUid, chatId);
    };
    mref.on('value', mh);
    // Read receipts: re-render ticks when the other side's read pointer moves.
    const rref = _db.ref(`chats/${chatId}/meta/read`);
    const rh = snap => { _chatReadMeta = snap.val() || {}; renderChatMessages(_lastChatMsgs); };
    rref.on('value', rh);
    // Typing indicator: repaint the header when the other side starts/stops typing.
    const tref = _db.ref(`chats/${chatId}/meta/typing`);
    const th = snap => { _chatTyping = snap.val() || {}; paintChatHeaderStatus(); };
    tref.on('value', th);
    // Tick so a stale "печатает…" fades on its own even without a new event.
    const typingTick = setInterval(paintChatHeaderStatus, 2500);
    _chatListenerOff = () => { mref.off('value', mh); rref.off('value', rh); tref.off('value', th); clearInterval(typingTick); };
  }

  // Detect a 1–3 emoji-only message so it can render big & bubble-less (jumbo), like Telegram.
  function emojiOnlyCount(text) {
    const t = (text || '').trim();
    if (!t) return 0;
    if (!/\p{Extended_Pictographic}/u.test(t)) return 0;
    // Strip emoji + modifiers + ZWJ + variation selectors + regional indicators + keycap mark.
    const stripped = t.replace(/[\p{Extended_Pictographic}\u{1F1E6}-\u{1F1FF}\u{1F3FB}-\u{1F3FF}\uFE0F\uFE0E\u200D\u20E3\s]/gu, '');
    if (stripped.length > 0) return 0; // contains real text → not jumbo
    try {
      if (typeof Intl !== 'undefined' && Intl.Segmenter) {
        return [...new Intl.Segmenter('en', { granularity: 'grapheme' }).segment(t)].length;
      }
    } catch (_) {}
    return (t.match(/\p{Extended_Pictographic}/gu) || []).length;
  }

  // Telegram-style reaction "pop": a big emoji + sparkle ring at the bubble.
  function burstReactionAt(mid, emoji) {
    const bubble = document.querySelector(`#chat-body .chat-bubble[data-mid="${mid}"]`);
    if (!bubble) return;
    const anchor = bubble.querySelector('.chat-reactions') || bubble;
    const r = anchor.getBoundingClientRect();
    if (!r.width && !r.height) return;
    const cx = r.left + Math.min(r.width, 44) / 2;
    const cy = r.top + r.height / 2;
    const pop = document.createElement('div');
    pop.className = 'react-burst';
    pop.textContent = emoji;
    pop.style.left = cx + 'px'; pop.style.top = cy + 'px';
    document.body.appendChild(pop);
    setTimeout(() => pop.remove(), 720);
    for (let i = 0; i < 6; i++) {
      const s = document.createElement('div');
      s.className = 'react-spark';
      const ang = (Math.PI * 2 * i) / 6 + Math.random() * 0.5;
      const dist = 20 + Math.random() * 16;
      s.style.left = cx + 'px'; s.style.top = cy + 'px';
      s.style.setProperty('--bx', (Math.cos(ang) * dist).toFixed(1) + 'px');
      s.style.setProperty('--by', (Math.sin(ang) * dist).toFixed(1) + 'px');
      s.style.animationDelay = (i * 12) + 'ms';
      document.body.appendChild(s);
      setTimeout(() => s.remove(), 720);
    }
  }

  // Кликабельные ссылки/юзернеймы в сообщениях (как в Telegram): экранируем текст,
  // затем оборачиваем URL и t.me-ссылки в <a>. Нужно, чтобы Telegram-ссылка в
  // автоответе на заявку тарифа была кликабельной (просьба 09.07).
  function linkifyChat(text) {
    const esc = escHtml(text || '');
    return esc.replace(/(https?:\/\/[^\s<]+|(?:www\.|t\.me\/)[^\s<]+)/g, (u) => {
      const href = /^https?:\/\//.test(u) ? u : 'https://' + u;
      return `<a href="${href}" target="_blank" rel="noopener" class="chat-link">${u}</a>`;
    });
  }
  function renderChatMessages(msgs) {
    const body = document.getElementById('chat-body');
    if (!body) return;
    const me = myUid();
    // ✓✓ logic: DM — the other side's read pointer; group — the freshest read among other members.
    let otherRead = 0;
    if (_chatIsGroup) {
      Object.entries(_chatReadMeta || {}).forEach(([uid, ts]) => {
        if (uid !== me && Number(ts) > otherRead) otherRead = Number(ts);
      });
    } else {
      otherRead = (_chatOtherUid && _chatReadMeta && _chatReadMeta[_chatOtherUid]) || 0;
    }
    const entries = Object.entries(msgs).map(([k, v]) => ({ key: k, ...v })).sort((a, b) => (a.at || 0) - (b.at || 0));
    if (!entries.length) {
      body.innerHTML = `<div style="text-align:center;padding:36px 24px;color:var(--soft);font-size:12px;">${t('ui.127')}<br>${t('ui.127')}</div>`;
      _chatSeenKeys = new Set();
      _chatLastRenderedSig = null;
      return;
    }
    const firstPaint = _chatSeenKeys === null; // don't animate history when a chat opens
    // Keep the user's place if they scrolled up to read history.
    const nearBottom = (body.scrollHeight - body.scrollTop - body.clientHeight) < 90;
    let lastDay = '';
    let prevFrom = '';
    let html = '';
    for (const m of entries) {
      const d = new Date(m.at || Date.now());
      const dayKey = d.toDateString();
      if (dayKey !== lastDay) {
        html += `<div class="chat-day-label"><span>${escHtml(formatChatDay(d))}</span></div>`;
        lastDay = dayKey;
        prevFrom = ''; // a day break restarts the sender-name grouping
      }
      // Системное сообщение (вошёл/вышел/создал) — по центру, без пузыря
      if (m.type === 'system') {
        html += `<div class="chat-system"><span>${escHtml(m.text || '')}</span></div>`;
        prevFrom = '';
        continue;
      }
      const mine = m.from === me;
      // Group chats: show the sender name on the first bubble of each run (Telegram-style).
      const senderHtml = (_chatIsGroup && !mine && m.from !== prevFrom)
        ? `<div class="chat-sender-name nc-${nameColorIdx(m.from)}">${escHtml(m.fromName || (_chatMembers && _chatMembers[m.from]) || t('grp.defMember'))}</div>`
        : '';
      prevFrom = m.from;
      const time = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
      // Reply quote
      const replyHtml = m.replyTo ? `
        <div class="chat-reply-quote">
          <div class="crq-name">${escHtml(m.replyTo.fromName || '')}</div>
          <div class="crq-text">${escHtml((m.replyTo.text || '').slice(0, 120))}</div>
        </div>` : '';
      // Reactions (grouped emoji chips)
      let reactHtml = '';
      if (m.reactions && typeof m.reactions === 'object') {
        const counts = {};
        Object.values(m.reactions).forEach(em => { if (em) counts[em] = (counts[em] || 0) + 1; });
        const myEm = m.reactions[me] || '';
        const chips = Object.entries(counts).map(([em, n]) =>
          `<button class="chat-react-chip ${myEm === em ? 'mine' : ''}" onclick="event.stopPropagation(); reactMessage('${m.key}','${em}')">${em}${n > 1 ? ` ${n}` : ''}</button>`).join('');
        if (chips) reactHtml = `<div class="chat-reactions">${chips}</div>`;
      }
      // Delivery ticks on my own messages (✓ sent / ✓✓ read — visible to both)
      const tick = mine ? `<span class="chat-tick ${otherRead >= (m.at || 0) ? 'read' : ''}">${otherRead >= (m.at || 0) ? '✓✓' : '✓'}</span>` : '';
      // Jumbo: 1–3 emoji only → big, no bubble chrome.
      const jc = emojiOnlyCount(m.text);
      const jumbo = (jc >= 1 && jc <= 3) ? ` jumbo jumbo-${jc}` : '';
      // Entrance animation only for messages that appeared after the chat was open.
      const isNew = _chatSeenKeys && !_chatSeenKeys.has(m.key);
      const enter = isNew ? (mine ? ' chat-enter-mine' : ' chat-enter') : '';
      html += `
        <div class="chat-msg-row ${mine ? 'mine' : 'theirs'}">
          <div class="chat-bubble ${mine ? 'mine' : 'theirs'}${jumbo}${enter}" data-mid="${m.key}">
            ${senderHtml}
            ${replyHtml}
            <div class="chat-bubble-text">${linkifyChat(m.text)}</div>
            <div class="chat-bubble-meta"><span class="chat-bubble-time">${time}</span>${tick}</div>
            ${reactHtml}
          </div>
        </div>`;
    }
    // Перерисовываем ТОЛЬКО при реальных изменениях. На каждое сообщение рендер
    // прилетал дважды-трижды подряд (эхо моего markChatRead через снапшот meta/read,
    // тикер typing) — полный innerHTML обрывал entrance-анимацию пузыря и «мигал»
    // чатом. Сигнатура без enter-классов: повтор с тем же содержимым — тихий выход.
    const sig = html.replace(/ chat-enter(-mine)?/g, '');
    if (sig === _chatLastRenderedSig) return;
    _chatLastRenderedSig = sig;
    body.innerHTML = html;
    if (nearBottom) body.scrollTop = body.scrollHeight;
    // Reaction burst: animate reactions that appeared since the previous render (either side).
    const curReactions = {};
    for (const m of entries) {
      if (m.reactions && typeof m.reactions === 'object') curReactions[m.key] = { ...m.reactions };
      if (!firstPaint) {
        const prev = _chatPrevReactions[m.key] || {};
        const cur = curReactions[m.key] || {};
        for (const uid in cur) {
          if (cur[uid] && cur[uid] !== prev[uid]) burstReactionAt(m.key, cur[uid]);
        }
      }
    }
    _chatPrevReactions = curReactions;
    if (firstPaint) _chatSeenKeys = new Set();
    entries.forEach(m => _chatSeenKeys.add(m.key));
  }

  function formatChatDay(d) {
    const today = new Date();
    today.setHours(0,0,0,0);
    const day = new Date(d);
    day.setHours(0,0,0,0);
    const diffDays = Math.round((today - day) / 86400000);
    if (diffDays === 0) return 'Сегодня';
    if (diffDays === 1) return 'Вчера';
    const months = ['янв','фев','мар','апр','мая','июн','июл','авг','сен','окт','ноя','дек'];
    return `${d.getDate()} ${months[d.getMonth()]}`;
  }

  async function sendCurrentChatMessage(otherUid, otherName) {
    const inp = document.getElementById('chat-input');
    if (!inp) return;
    const text = inp.value;
    if (!text.trim()) return;
    inp.value = '';
    await sendChatMessage(otherUid, otherName, text);
    inp.focus();
  }

  // ─────────────────────────── PUSH NOTIFICATIONS (FCM) ───────────────────────────
  // Foreground (site open): show in-app toast + sound; the OS banner is suppressed
  //   for the chat that's currently open so the user isn't spammed about their
  //   own active conversation.
  // Background (site minimized / closed): firebase-messaging-sw.js handles it and
  //   the browser/OS draws the banner.
  let _pushInitDone = false;
  let _pushUnsubFg = null;
  let _pushCurrentToken = null;

  async function initPushNotifications() {
    if (_pushInitDone) return;
    if (!_messaging) return; // unsupported browser (e.g. Safari on older iOS, file://)
    if (!('Notification' in window)) return;
    if (!isLoggedInForChat()) return;
    if (!_VAPID_KEY || _VAPID_KEY.startsWith('REPLACE_')) {
      console.warn('[push] VAPID key not configured — skipping push setup');
      return;
    }
    _pushInitDone = true;

    // Register the service worker explicitly. Default `firebase-messaging-sw.js`
    // at site root is picked up automatically, but doing it manually lets us
    // pass it to getToken and avoid race conditions on slow connections.
    let swReg;
    try {
      swReg = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
    } catch (e) {
      console.warn('[push] SW register failed', e);
      return;
    }

    // Don't auto-prompt — wait until the user explicitly asks (see askPushPermission)
    if (Notification.permission !== 'granted') return;
    await registerFcmToken(swReg);
    attachForegroundMessageHandler();
  }

  async function askPushPermission() {
    if (!_messaging) { toast(t('ui.129')); return; }
    if (!('Notification' in window)) { toast(t('ui.130')); return; }
    if (!_VAPID_KEY || _VAPID_KEY.startsWith('REPLACE_')) {
      toast(t('ui.131'));
      return;
    }
    if (Notification.permission === 'granted') {
      toast(t('push.alreadyOn'), 'var(--sage)');
      return;
    }
    if (Notification.permission === 'denied') {
      toast(t('ui.132'));
      return;
    }
    const res = await Notification.requestPermission();
    if (res !== 'granted') {
      toast(t('ui.133'));
      return;
    }
    let swReg;
    try {
      swReg = await navigator.serviceWorker.register('/firebase-messaging-sw.js');
    } catch (e) { console.warn('[push] SW register failed', e); return; }
    await registerFcmToken(swReg);
    attachForegroundMessageHandler();
    toast(t('push.enabled'), 'var(--sage)');
    renderSettingsCard(); // строка «Уведомления» сразу показывает «ВКЛ ✓»
  }

  async function registerFcmToken(swReg) {
    try {
      const token = await _messaging.getToken({
        vapidKey: _VAPID_KEY,
        serviceWorkerRegistration: swReg
      });
      if (!token) { console.warn('[push] empty token'); return; }
      _pushCurrentToken = token;
      const uid = firebaseUserId();
      if (!uid || uid === 'guest') return;
      // Save under users/{uid}/fcmTokens/{token} = lastUpdatedAt — the Cloud
      // Function reads this list to deliver pushes. Storing as a sub-key (not
      // a value) lets us prune invalid tokens individually.
      await _db.ref(`users/${uid}/fcmTokens/${token}`).set(Date.now());
    } catch (e) {
      console.warn('[push] getToken failed', e);
    }
  }

  function attachForegroundMessageHandler() {
    if (!_messaging || _pushUnsubFg) return;
    _pushUnsubFg = _messaging.onMessage(payload => {
      const data = payload.data || {};
      const noti = payload.notification || {};
      const title = noti.title || data.fromName || t('chat.newMsg');
      const body  = noti.body  || '';
      // Suppress if the chat with that sender is already open
      const fromUid = data.from || '';
      const chatId  = data.chatId || '';
      if (chatId && _chatCurrentId === chatId) {
        // Same chat is open — message will appear in real time anyway
        return;
      }
      // In-app banner (same component as the realtime popup, deduped by sender uid)
      try {
        if (fromUid) showChatPopup(fromUid, title, (data.fromAvatar || ''), body);
        else toast(`💬 ${title}: ${body.length > 60 ? body.slice(0, 60) + '…' : body}`, 'var(--berry)');
      } catch (_) {}
      // Some browsers also fire the SW notification while the page is foregrounded;
      // others don't. We render it ourselves so behavior is consistent.
      try {
        if (Notification.permission === 'granted' && document.hidden) {
          new Notification(title, {
            body, icon: '/assets/logo-app.png', tag: chatId ? `chat-${chatId}` : undefined
          });
        }
      } catch (_) {}
    });
  }

  // Listen for SW → page messages: "open chat X" when user taps the notification
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.addEventListener('message', ev => {
      const m = ev.data || {};
      if (m.kind === 'fcm-notification-click' && m.data && m.data.from) {
        const fromUid = m.data.from;
        const fromName = m.data.fromName || 'Друг';
        try { switchScreen('profile'); } catch (_) {}
        try { openChat(fromUid, fromName); } catch (_) {}
      }
    });
  }

  // ─────────────────────────── РЕФЕРАЛКА ───────────────────────────
  const REFERRAL_XP = 200;
  // захват ?ref=... при загрузке (до регистрации)
  (function captureRef() {
    try {
      const ref = new URLSearchParams(location.search).get('ref');
      if (ref && !Store.get('user')) Store.set('pendingRef', ref);
    } catch (_) {}
  })();
  function shareInviteLink() {
    const u = Store.get('user');
    const uid = (typeof firebaseUserId === 'function' ? firebaseUserId() : '') || '';
    if (!u || u.guest || !uid || uid === 'guest') { toast(t('inv.needLogin')); return; }
    const link = location.origin + location.pathname + '?ref=' + encodeURIComponent(uid);
    const text = t('inv.text', { xp: REFERRAL_XP, link: link });
    if (navigator.share) {
      navigator.share({ title: 'Korean with Madie', text }).catch(() => {});
    } else {
      navigator.clipboard?.writeText(text).then(
        () => toast(t('inv.copied'), 'var(--sage)'),
        () => toast(link, 'var(--berry)')
      );
    }
  }
  // вызвать после успешной регистрации нового пользователя
  function applyPendingReferral(newUid, newName) {
    const refUid = Store.get('pendingRef');
    if (!refUid || typeof _db === 'undefined') return;
    Store.del('pendingRef');
    if (!newUid || refUid === newUid) return;
    try {
      _db.ref('shared/referrals').push({ newUid, newName: newName || '', refUid, ts: Date.now() });
      // награда пригласившему — письмо в его inbox (его клиент начислит XP)
      _db.ref('users/' + refUid + '/inbox').push({ type: 'referral', fromName: newName || 'Новый ученик', ts: Date.now() });
      // награда новичку — сразу
      setTimeout(() => {
        addXp(REFERRAL_XP, false);
        grantMasterDays(7, 'referral-new');
        toast(t('ui.134',{xp: REFERRAL_XP}), 'var(--sage)');
      }, 1500);
    } catch (_) {}
  }
  // пригласивший получает свои XP, когда его клиент видит письмо type='referral'
  function processReferralRewards() {
    if (typeof _db === 'undefined') return;
    const me = (typeof firebaseUserId === 'function' ? firebaseUserId() : '') || '';
    if (!me || me === 'guest') return;
    Object.entries(_inboxCache || {}).forEach(([key, v]) => {
      if (!v || v.type !== 'referral' || v.claimed) return;
      v.claimed = true; // локальная пометка в _inboxCache: повторная сработка листенера до отражения remove() не должна начислить награду дважды
      _db.ref(`users/${me}/inbox/${key}`).remove();
      addXp(REFERRAL_XP, false);
      grantMasterDays(7, 'referral-inviter');
      stats.referralsCount = (stats.referralsCount || 0) + 1;
      UStore.set('stats', stats);
      renderInviteCard();
      toast(t('ui.r039',{name: escHtml(v.fromName || t('common.friendFallback')), xp: REFERRAL_XP}), 'var(--sage)');
    });
  }

  // ─────────────────────────── НАСТРОЙКИ ПРИЛОЖЕНИЯ ───────────────────────────
  const SETTINGS_DEFAULTS = { sound: true, slowVoice: false, voiceEngine: 'auto', petals: true, calmMotion: false, scape: null, scapeVol: 0.5, darkTheme: false, darkAuto: false, colorTheme: 'madie', gender: '' };
  // Пол пользователя ('f'|'m'|''). Пусто → спрашиваем. Гендерные обращения по всему UI.
  function userGender() {
    const g = getSettings().gender;
    return (g === 'm' || g === 'f') ? g : '';
  }
  // gw(женская_форма, мужская_форма) — выбирает по полу пользователя (по умолчанию женская).
  function gw(f, m) { return userGender() === 'm' ? m : f; }
  // Ручной выбор движка озвучки: 'auto' — натуральный с фолбэком, 'device' — сразу встроенный
  // (для учениц за блокировкой, чтобы не ждать таймаут; отзыв 08.07).
  function setVoiceEngine(v) {
    const s = getSettings();
    s.voiceEngine = (v === 'device') ? 'device' : 'auto';
    UStore.set('settings', s);
    if (s.voiceEngine === 'auto') _ttsMarkOk(); // вернулись вручную — даём натуральному чистый шанс
    renderSettingsCard();
    toast(s.voiceEngine === 'device' ? t('set.voice.toastDevice') : t('set.voice.toastAuto'), 'var(--ok-ink)');
  }
  function setGender(g) {
    const s = getSettings();
    s.gender = (g === 'm') ? 'm' : 'f';
    UStore.set('settings', s);
    renderSettingsCard();
    // Перерисовать ВСЕ места с гендерными обращениями: ранг в шапке/карточке (syncStats),
    // полоска достижений, открытый профиль и чип уровня.
    try { syncStats(); } catch (_) {}
    try { syncAchievementsStrip(); } catch (_) {}
    try { renderMyLevelChip(); } catch (_) {}
    try { if (_curScreen === 'profile') switchScreen('profile', true); } catch (_) {}
    toast(g === 'm' ? t('settings.genderSetM') : t('settings.genderSetF'), 'var(--berry)');
  }
  // Для конкретного пользователя (ученика в админке): пол берём из meta.gender 'Ж'/'М'.
  function gwFor(metaGender, f, m) { return metaGender === 'М' ? m : f; }
  // ── Цветовые темы (свотчи в Настройках; CSS-классы ct-* в styles.css) ──
  const COLOR_THEMES = [
    { key: 'madie',   name: 'Madie',     a: '#D9687A', b: '#FBE8EA' },
    { key: 'emerald', name: 'Изумруд',   a: '#3A6F69', b: '#D2FBF7' },
    { key: 'blossom', name: 'Роза·лайм', a: '#EEC1DF', b: '#E3FB9E' },
    { key: 'lime',    name: 'Лайм',      a: '#494949', b: '#C3FA4E' },
    { key: 'sky',     name: 'Небо',      a: '#A0D3F7', b: '#F7EDC0' },
    { key: 'mono',    name: 'Ч/б',       a: '#2B2B2B', b: '#F5F5F5' }
  ];
  function setColorTheme(key) {
    if (!COLOR_THEMES.some(t => t.key === key)) return;
    const s = getSettings();
    s.colorTheme = key;
    // Свотч и тёмный режим независимы: для каждой темы есть тёмный вариант,
    // поэтому выбор темы СОХРАНЯЕТ текущий светлый/тёмный режим.
    UStore.set('settings', s);
    applySettings();
    // Обновляем активный свотч на месте, без перерисовки карточки
    document.querySelectorAll('#settings-card .theme-swatch-wrap').forEach(b =>
      b.classList.toggle('active', b.dataset.theme === key));
    const theme = COLOR_THEMES.find(th => th.key === key);
    toast(t('ui.135',{name: theme ? theme.name : ''}), 'var(--berry)');
  }
  // Ночь для авто-тёмной темы: с 20:00 до 08:00
  function isNightTime() {
    const h = new Date().getHours();
    return h >= 20 || h < 8;
  }
  let _darkAutoTimer = null;
  function getSettings() {
    const s = UStore.get('settings', null);
    return { ...SETTINGS_DEFAULTS, ...(s && typeof s === 'object' ? s : {}) };
  }
  function toggleSetting(key) {
    const s = getSettings();
    s[key] = !s[key];
    UStore.set('settings', s);
    applySettings();
    // Плавно: переключаем класс на месте, без перерисовки всей карточки
    const sw = document.querySelector(`#settings-card [data-setting="${key}"] .switch`);
    if (sw) sw.classList.toggle('on', s[key]); else renderSettingsCard();
    if (key === 'sound') toast(s.sound ? t('settings.soundOnToast') : t('settings.soundOffToast'), 'var(--berry)');
  }
  function openSettingsModal() {
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'settings-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:420px; max-height:84vh; display:flex; flex-direction:column;">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-shrink:0;">
          <div style="display:flex; align-items:center; gap:10px;">
            <span style="width:36px; height:36px; border-radius:12px; background:var(--blush); display:flex; align-items:center; justify-content:center; font-size:17px;"><i class="fa-solid fa-gear" style="color:var(--coral);"></i></span>
            <div class="display" style="font-size:20px; color:var(--berry);" data-i18n="set.title">Настройки</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px; color:var(--soft); cursor:pointer; padding:2px 6px;">×</div>
        </div>
        <div style="overflow-y:auto; min-height:0;">
          <div id="settings-card" style="padding:0 4px;"></div>
          <div style="text-align:center; padding:14px 0 6px; font-size:10.5px; color:var(--hush);" data-i18n="set.footer">Korean with Madie · сделано с 🌸</div>
        </div>
      </div>`;
    document.body.appendChild(m);
    renderSettingsCard();
    applyStaticI18n(m);
  }
  function applySettings() {
    const s = getSettings();
    document.body.classList.toggle('no-petals', !s.petals);
    document.body.classList.toggle('calm-motion', s.calmMotion);
    // Тёмная тема: вручную ИЛИ авто-режимом ночью (20:00–08:00)
    const dark = !!s.darkTheme || (s.darkAuto && isNightTime());
    document.body.classList.toggle('theme-dark', dark);
    // Цветовая тема: один класс ct-<key>; 'madie' — родная палитра без класса.
    // Свотч применяется И в светлой, И в тёмной теме: для каждого ct-* есть тёмный
    // вариант body.ct-X.theme-dark (акцент в цвет темы, поверхности — тёмные).
    // Светлые !important-оверрайды свотчей (ч/б .topik-hero и т.п.) защищены :not(.theme-dark).
    COLOR_THEMES.forEach(t => { if (t.key !== 'madie') document.body.classList.remove('ct-' + t.key); });
    if (s.colorTheme && s.colorTheme !== 'madie') document.body.classList.add('ct-' + s.colorTheme);
    // Авто-режим: раз в минуту проверяем, не наступила ли ночь/утро
    if (s.darkAuto && !_darkAutoTimer) _darkAutoTimer = setInterval(applySettings, 60000);
    if (!s.darkAuto && _darkAutoTimer) { clearInterval(_darkAutoTimer); _darkAutoTimer = null; }
    const meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute('content', dark ? '#121212' : '#FFFAF6');
  }
  function renderSettingsCard() {
    const slot = document.getElementById('settings-card');
    if (!slot) return;
    const s = getSettings();
    const pushPerm = !('Notification' in window) ? 'unsupported' : Notification.permission;
    const pushState = pushPerm === 'unsupported' ? t('set.notif.unsup')
      : pushPerm === 'granted' ? t('set.notif.on')
      : pushPerm === 'denied' ? t('set.notif.denied')
      : t('set.notif.off');
    const pushRight = pushPerm === 'granted'
      ? `<span class="chip chip-sage" style="font-size:9px; padding:3px 9px;">${t('set.notif.onChip')}</span>`
      : pushPerm === 'denied'
        ? `<span class="chip chip-coral" style="font-size:9px; padding:3px 9px;">${t('set.notif.block')}</span>`
        : `<i class="fa-solid fa-chevron-right" style="color:var(--coral); font-size:11px;"></i>`;
    const row = (ico, title, sub, right, onclick, key) => `
      <button type="button" class="settings-row" ${key ? `data-setting="${key}"` : ''} onclick="${onclick}">
        <span class="settings-ico">${ico}</span>
        <span class="settings-tx">
          <span class="settings-title" style="display:block;">${title}</span>
          ${sub ? `<span class="settings-sub" style="display:block;">${sub}</span>` : ''}
        </span>
        ${right}
      </button>`;
    const sw = on => `<span class="switch ${on ? 'on' : ''}"></span>`;
    const chev = `<i class="fa-solid fa-chevron-right" style="color:var(--coral); font-size:11px;"></i>`;
    slot.innerHTML = [
      `<div class="theme-picker">
        <div class="theme-picker-title">🌐 ${t('set.lang')} <span style="font-weight:500; color:var(--hush); font-size:10.5px;">— ${t('set.lang.sub')}</span></div>
        <div class="gender-pick-row" style="flex-wrap:wrap;">
          ${I18N_LANGS.map(lng => `<button type="button" class="gender-opt ${APP_LANG === lng ? 'active' : ''}" onclick="setAppLang('${lng}')">${I18N_LANG_NAMES[lng]}</button>`).join('')}
        </div>
      </div>`,
      row('🔊', t('set.sound'), t('set.sound.sub'), sw(s.sound), "toggleSetting('sound')", 'sound'),
      row('🐢', t('set.slow'), t('set.slow.sub'), sw(s.slowVoice), "toggleSetting('slowVoice')", 'slowVoice'),
      `<div class="gender-pick">
        <div class="gender-pick-title">🗣️ ${t('set.voice')} <span style="font-weight:500; color:var(--hush); font-size:10.5px;">${t('set.voice.note')}</span></div>
        <div class="gender-pick-row">
          <button type="button" class="gender-opt ${(s.voiceEngine || 'auto') === 'auto' ? 'active' : ''}" onclick="setVoiceEngine('auto')">${t('set.voice.auto')}</button>
          <button type="button" class="gender-opt ${s.voiceEngine === 'device' ? 'active' : ''}" onclick="setVoiceEngine('device')">${t('set.voice.device')}</button>
        </div>
      </div>`,
      row('🌸', t('set.petals'), t('set.petals.sub'), sw(s.petals), "toggleSetting('petals')", 'petals'),
      row('🕊️', t('set.calm'), t('set.calm.sub'), sw(s.calmMotion), "toggleSetting('calmMotion')", 'calmMotion'),
      row('🌙', t('set.dark'), t('set.dark.sub'), sw(s.darkTheme), "toggleSetting('darkTheme')", 'darkTheme'),
      row('🌗', t('set.darkAuto'), t('set.darkAuto.sub'), sw(s.darkAuto), "toggleSetting('darkAuto')", 'darkAuto'),
      `<div class="theme-picker">
        <div class="theme-picker-title">🎨 ${t('set.color')} <span style="font-weight:500; color:var(--hush); font-size:10.5px;">${t('set.color.note')}</span></div>
        <div class="theme-swatches">
          ${COLOR_THEMES.map(th => `
            <button type="button" class="theme-swatch-wrap ${s.colorTheme === th.key ? 'active' : ''}" data-theme="${th.key}" onclick="setColorTheme('${th.key}')" aria-label="${th.name}">
              <span class="theme-swatch"><span style="background:${th.a}"></span><span style="background:${th.b}"></span><i class="fa-solid fa-check" aria-hidden="true"></i></span>
              <span class="theme-swatch-name">${th.name}</span>
            </button>`).join('')}
        </div>
      </div>`,
      `<div class="gender-pick" ${s.gender ? '' : 'data-required="1"'}>
        <div class="gender-pick-title">🧑 ${t('set.gender')} <span style="font-weight:500; color:var(--hush); font-size:10.5px;">${t('set.gender.note')}${s.gender ? '' : t('set.gender.ask')}</span></div>
        <div class="gender-pick-row">
          <button type="button" class="gender-opt ${s.gender === 'f' ? 'active' : ''}" onclick="setGender('f')">${t('set.gender.f')}</button>
          <button type="button" class="gender-opt ${s.gender === 'm' ? 'active' : ''}" onclick="setGender('m')">${t('set.gender.m')}</button>
        </div>
      </div>`,
      ...((Store.get('user') && !Store.get('user').isAdmin) ? [
        row('💎', t('set.plan'), t('set.plan.sub', { plan: `${PLANS[myPlanId()].emoji} ${PLANS[myPlanId()].name}` }), chev, "document.getElementById('settings-modal')?.remove(); openPlanPage()")
      ] : []),
      row('🌸', t('set.intro'), t('set.intro.sub'), chev, 'startOnboardingTour()'),
      row('🧭', t('set.tour'), t('set.tour.sub'), chev, 'startAppTour()'),
      row('🎯', t('set.goal'), t('set.goal.sub'), chev, 'openDailyGoalSettings()'),
      row('🔔', t('set.notif'), pushState, pushRight, 'askPushPermission()'),
      row('💌', t('set.feedback'), t('set.feedback.sub'), chev, 'openFeedbackModal()'),
      row('📜', t('set.terms'), t('set.terms.sub'), chev, 'showTermsModal()'),
      ...(Store.get('user') ? [
        row('✏️', t('set.editProfile'), t('set.editProfile.sub'), chev, "document.getElementById('settings-modal')?.remove(); showEditProfile()"),
        row('🚪', t('set.logout'), t('set.logout.sub'), `<i class="fa-solid fa-arrow-right-from-bracket" style="color:var(--bad-ink); font-size:13px;"></i>`, "document.getElementById('settings-modal')?.remove(); logoutUser()")
      ] : [])
    ].join('');
  }

  // ─────────────────────────── ОБРАТНАЯ СВЯЗЬ ───────────────────────────
  let _fbType = 'idea';
  function openFeedbackModal(presetType) {
    _fbType = presetType || 'idea';
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.id = 'feedback-modal';
    m.onclick = e => { if (e.target === m) m.remove(); };
    m.innerHTML = `
      <div class="modal-card" style="max-width:400px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:12px;">
          <div>
            <div class="page-eyebrow">${t('fb.eyebrow')}</div>
            <div class="display" style="font-size:20px; color:var(--berry); margin-top:4px;">${t('fb.title')}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px; color:var(--soft); cursor:pointer;">×</div>
        </div>
        <div style="font-size:12px; color:var(--soft); margin-bottom:12px; line-height:1.5;">${t('fb.desc')}</div>
        <div style="display:flex; gap:8px; margin-bottom:12px;">
          ${[['idea','fb.idea'],['bug','fb.bug'],['other','fb.other']].map(([k,lk]) =>
            `<button type="button" data-fbtype="${k}" onclick="setFbType('${k}')" class="auth-tab ${k===_fbType?'auth-tab-active':''}" style="flex:1; font-size:12px; padding:9px 4px;">${t(lk)}</button>`).join('')}
        </div>
        <textarea id="fb-text" class="input" rows="4" placeholder="${escAttr(t('fb.ph'))}" style="resize:vertical; min-height:96px; padding-top:10px;"></textarea>
        <button onclick="submitFeedback(this)" class="btn btn-primary btn-block" style="margin-top:12px;">${t('fb.send')}</button>
        <div style="text-align:center; font-size:10.5px; color:var(--hush); margin-top:8px;">${t('fb.note')}</div>
      </div>`;
    document.body.appendChild(m);
    setTimeout(() => document.getElementById('fb-text')?.focus(), 60);
  }
  function setFbType(t) {
    _fbType = t;
    document.querySelectorAll('#feedback-modal [data-fbtype]').forEach(b =>
      b.classList.toggle('auth-tab-active', b.getAttribute('data-fbtype') === t));
  }
  function submitFeedback(btn) {
    const ta = document.getElementById('fb-text');
    const text = (ta && ta.value || '').trim();
    if (text.length < 5) { toast(t('fb.tooShort')); return; }
    if (typeof _db === 'undefined') { toast(t('fb.noConn')); return; }
    const u = Store.get('user') || {};
    if (btn) { btn.disabled = true; btn.textContent = t('fb.sending'); }
    _db.ref('shared/feedback').push({
      type: _fbType,
      text: text.slice(0, 2000),
      name: u.name || t('auth.guest'),
      email: u.email || '',
      uid: (typeof firebaseUserId === 'function' ? firebaseUserId() : '') || '',
      ts: Date.now(),
      ua: (navigator.userAgent || '').slice(0, 160),
      done: false
    }).then(() => {
      document.getElementById('feedback-modal')?.remove();
      toast(t('fb.thanks'), 'var(--sage)');
    }).catch(e => {
      if (btn) { btn.disabled = false; btn.textContent = t('fb.send'); }
      const denied = e && (e.code === 'PERMISSION_DENIED' || /permission/i.test(e.message || ''));
      toast(denied ? t('fb.denied') : t('fb.failed'));
    });
  }

  // — Админ: входящие письма —
  let _feedbackCache = null;
  let _feedbackRefOn = false;
  function ensureFeedbackListener() {
    if (_feedbackRefOn || typeof _db === 'undefined') return;
    _feedbackRefOn = true;
    _db.ref('shared/feedback').on('value', snap => {
      _feedbackCache = snap.val() || {};
      if (adminCurrentTab === 'inbox') renderProfileAdminPanel('inbox');
      else if (adminCurrentTab === 'hub') renderProfileAdminPanel('hub'); // бейдж на карточке «Письма»
      const badge = document.getElementById('admin-inbox-count');
      if (badge) {
        const fresh = Object.values(_feedbackCache).filter(f => f && !f.done).length;
        badge.textContent = fresh || '';
      }
    });
  }
  function renderAdminInbox() {
    ensureFeedbackListener();
    if (_feedbackCache === null) {
      return `<div style="text-align:center; padding:24px; color:var(--soft); font-size:12px;">${t('ui.136')}</div>`;
    }
    const items = Object.entries(_feedbackCache)
      .map(([id, f]) => ({ id, ...(f || {}) }))
      .sort((a, b) => (b.ts || 0) - (a.ts || 0));
    if (!items.length) {
      return `<div style="text-align:center; padding:24px; color:var(--soft); font-size:12px;">${t('ui.137')}</div>`;
    }
    const typeLabel = { idea: '💡 Идея', bug: '🐞 Ошибка', other: '💬 Другое' };
    return `<div style="display:grid; gap:10px;">${items.map(f => `
      <div class="card card-padded" style="${f.done ? 'opacity:.6;' : ''}">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:6px;">
          <span class="chip ${f.type === 'bug' ? 'chip-coral' : 'chip-blush'}" style="font-size:10px;">${typeLabel[f.type] || '💬'}</span>
          <span style="font-size:10px; color:var(--hush);">${f.ts ? new Date(f.ts).toLocaleString('ru-RU', { day:'numeric', month:'short', hour:'2-digit', minute:'2-digit' }) : ''}</span>
        </div>
        <div style="font-size:13px; color:var(--ink); line-height:1.55; white-space:pre-wrap; word-break:break-word;">${escHtml(f.text || '')}</div>
        <div style="font-size:10.5px; color:var(--soft); margin-top:8px;">${escHtml(f.name || t('auth.guest'))}${f.email ? ` · ${escHtml(f.email)}` : ''}</div>
        <div style="display:flex; gap:8px; margin-top:10px;">
          <button onclick="adminToggleFeedbackDone('${f.id}', ${f.done ? 'false' : 'true'})" class="btn btn-ghost" style="flex:1; padding:7px 8px; font-size:11px;">${f.done ? '↩ Вернуть в новые' : '✓ Прочитано'}</button>
          <button onclick="adminDeleteFeedback('${f.id}')" class="btn btn-ghost" style="padding:7px 12px; font-size:11px; color:var(--bad-ink); border-color:rgba(179,58,74,.25);"><i class="fa-solid fa-trash"></i></button>
        </div>
      </div>`).join('')}</div>`;
  }
  function adminToggleFeedbackDone(id, done) {
    if (!ensureAdminAccess() || typeof _db === 'undefined') return;
    _db.ref('shared/feedback/' + id + '/done').set(done);
  }
  function adminDeleteFeedback(id) {
    if (!ensureAdminAccess() || typeof _db === 'undefined') return;
    if (!confirm(t('ui.138'))) return;
    _db.ref('shared/feedback/' + id).remove();
  }

  // ─────────────────────────── УСЛОВИЯ ИСПОЛЬЗОВАНИЯ ───────────────────────────
  function showTermsModal() {
    const m = document.createElement('div');
    m.className = 'modal-bg modal-center';
    m.onclick = e => { if (e.target === m) m.remove(); };
    // Параметр НЕ называем t — иначе затеняет i18n-функцию t() (класс багов затенения)
    const h = txt => `<div style="font-weight:700; color:var(--berry); font-size:13.5px; margin:16px 0 6px;">${txt}</div>`;
    const p = txt => `<div style="font-size:12.5px; color:var(--ink); line-height:1.65;">${txt}</div>`;
    m.innerHTML = `
      <div class="modal-card" style="max-width:440px; max-height:84vh; display:flex; flex-direction:column;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:8px; flex-shrink:0;">
          <div>
            <div class="page-eyebrow">KOREAN WITH MADIE</div>
            <div class="display" style="font-size:20px; color:var(--berry); margin-top:4px;">${t('ui.139')}</div>
            <div style="font-size:10.5px; color:var(--hush); margin-top:3px;">${t('ui.140')}</div>
          </div>
          <div onclick="this.closest('.modal-bg').remove()" style="font-size:24px; color:var(--soft); cursor:pointer;">×</div>
        </div>
        <div style="overflow-y:auto; padding-right:6px; min-height:0;">
          ${Array.from({length: 14}, (_, i) => h(t('terms.s' + (i + 1) + '.h')) + p(t('terms.s' + (i + 1) + '.p'))).join('')}
          <div style="text-align:center; padding:18px 0 6px; font-size:11px; color:var(--hush);">${t('about.madeBy')}</div>
        </div>
        <button onclick="this.closest('.modal-bg').remove()" class="btn btn-primary btn-block" style="margin-top:12px; flex-shrink:0;">${t('ui.141')}</button>
      </div>`;
    document.body.appendChild(m);
  }

  // Per-user storage (namespace by current logged-in user)
  function currentUserId() {
    const u = Store.get('user');
    if (!u) return 'guest';
    if (u.isAdmin) return `admin_${(u.email || u.name).toLowerCase()}`;
    // Email — ключ хранилища. Если локальный объект временно потерял его (синк/вход
    // без email), восстанавливаем из активной Firebase-сессии, чтобы ключ НЕ съехал
    // на user_<имя> — иначе весь прогресс ученика «исчезает» под другим ключом.
    let email = u.email;
    if (!email && !u.guest && typeof _auth !== 'undefined' && _auth.currentUser && _auth.currentUser.email) {
      email = _auth.currentUser.email;
    }
    if (email) return `user_${email.toLowerCase()}`;
    if (u.guest) return 'guest';
    return `user_${(u.name || '').toLowerCase()}`;
  }
  function uKey(name) { return `u_${currentUserId()}_${name}`; }
  const UStore = {
    get(k, d=null) { return Store.get(uKey(k), d); },
    set(k, v) { Store.set(uKey(k), v); },
    del(k) { Store.del(uKey(k)); }
  };

  // Default stats schema (used as baseline for every new user/guest)
  function defaultStats() {
    return {
      xp: 0, streak: 0, lessons: 0, words: 0,
      firstOpenTs: null,
      dates: [], daysEntered: 0, minutesSpent: 0,
      gamePlays: {}, perfectGames: {}, wordsLearned: [],
      hangulSyllables: 0, hangulSaved: 0,
      pronunciationAttempts: 0, pronunciationCorrect: 0, pronunciationStreak: 0, pronunciationBestStreak: 0,
      hasAvatar: false, openedCalendar: false, openedCulture: false,
      // Daily goal — резетится каждый день в полночь по локальному времени
      dailyGoal: 30, dailyXp: 0, dailyDate: '', dailyGoalReachedDates: [],
      // XP earned per calendar day (for the weekly profile chart); pruned to ~30 days
      xpByDay: {},
      // Заморозка стрика (ФАЗА A1): frozenDates — «укрытые» пропущенные дни, считаются
      // в computeConsecutiveStreak наравне с dates, но НЕ в daysEntered (это не реальный вход).
      freezeCount: 0, frozenDates: [], freezeEarnedWeek: '',
      // ФАЗА A2: последний «ремонт» стрика (epoch ms) — лимит 1 раз в 30 дней
      lastRepairAt: 0,
      // ФАЗА A3: недельные квесты от Комдори + альбом стикеров-наград
      weekQuests: null, stickers: [],
      // ФАЗА A4: месячные агрегаты + флаг «отчёт за этот месяц уже показан»
      monthly: {}, lastReportShown: '',
      // ФАЗА E1: дни, когда была сыграна «игра дня» — для квеста A3 «сыграй в игру дня»
      gameOfDayPlayedDates: [],
      // ФАЗА T1: дни, когда пройден Блиц-10 — для квеста A3 «пройди Блиц-10»
      blitzPlayedDates: [],
      // ФАЗА B1: число друзей, чью рефералку засчитали (локальный счётчик, без чтения shared/referrals)
      referralsCount: 0,
      // ФАЗА C1: постоянные флаги лимитированных сезонных ачивок + «видел слова ивента N»
      seasonal: [], seasonalVisited: {},
      // ФАЗА D2: письменная практика RU→KO — {taskId, ts} за каждую отправленную на проверку/Мади работу
      writingSubmits: [],
      // ФАЗА D3: постоянный флаг статуса «Сонбэ» — церемония показывается только один раз
      sonbaeAwarded: false
    };
  }
  // In-memory stats (mutated, kept identical reference across user switches)
  const stats = defaultStats();

  // ФАЗА 0 (честные измерения игр): раньше rateCard засчитывал «партию» за каждую
  // перевёрнутую карточку, т.е. gamePlays.flashcards хранил карточки, а не сессии.
  // Одноразовая миграция: сырое значение → бэкап в gamePlaysLegacyFc, партии ≈ /15
  // (средняя длина сессии), карточки переезжают в новый счётчик fcCardsRated.
  // Идемпотентна (флаг = наличие gamePlaysLegacyFc) — облачный снапшот без флага
  // мигрируется заново, уже мигрированный не делится второй раз. Заработанные
  // ачивки games-* не страдают: unlocks хранятся отдельно и не отзываются.
  function migrateFcPlays(st) {
    if (!st || typeof st !== 'object') return false;
    if (st.gamePlaysLegacyFc !== undefined) return false; // уже мигрировано
    if (!st.gamePlays || typeof st.gamePlays !== 'object') st.gamePlays = {};
    const raw = Number(st.gamePlays.flashcards) || 0;
    st.gamePlaysLegacyFc = raw;
    if (raw > 0) {
      st.gamePlays.flashcards = Math.max(1, Math.round(raw / 15));
      if (st.fcCardsRated === undefined) st.fcCardsRated = raw;
    }
    return true;
  }

  // Load all per-user state from storage (call on init + after login/logout)
  function loadUserData() {
    // Chat ordering + popup state are per-user — reload them for this namespace.
    _chatLastAtLoaded = false; _prevUnreadFrom = null;
    const saved = UStore.get('stats') || {};
    Object.keys(stats).forEach(k => delete stats[k]);
    Object.assign(stats, defaultStats(), saved);
    if (!stats.firstOpenTs) { stats.firstOpenTs = Date.now(); UStore.set('stats', stats); }
    if (!Array.isArray(stats.wordsLearned)) stats.wordsLearned = [];
    if (!stats.gamePlays || typeof stats.gamePlays !== 'object') stats.gamePlays = {};
    if (!stats.perfectGames || typeof stats.perfectGames !== 'object') stats.perfectGames = {};
    if (!Array.isArray(stats.dates)) stats.dates = [];
    if (!Array.isArray(stats.frozenDates)) stats.frozenDates = [];
    if (typeof stats.freezeCount !== 'number' || stats.freezeCount < 0) stats.freezeCount = 0;
    if (!Array.isArray(stats.stickers)) stats.stickers = [];
    if (!stats.monthly || typeof stats.monthly !== 'object') stats.monthly = {};
    if (!Array.isArray(stats.gameOfDayPlayedDates)) stats.gameOfDayPlayedDates = [];
    if (!Array.isArray(stats.blitzPlayedDates)) stats.blitzPlayedDates = [];
    if (typeof stats.referralsCount !== 'number' || stats.referralsCount < 0) stats.referralsCount = 0;
    if (!Array.isArray(stats.seasonal)) stats.seasonal = [];
    if (!stats.seasonalVisited || typeof stats.seasonalVisited !== 'object') stats.seasonalVisited = {};
    if (!Array.isArray(stats.writingSubmits)) stats.writingSubmits = [];
    if (migrateFcPlays(stats)) UStore.set('stats', stats);
    _activeModule = UStore.get('activeModule') || 'm1';
    if (!LESSON_MODULES[_activeModule]) _activeModule = 'm1';
    // Если сохранённый модуль ещё не открыт (прогресс сброшен/не пройден) — откатываемся на m1
    if (!isModuleUnlocked(_activeModule) && !isAdmin()) _activeModule = 'm1';
    syncStats();
    syncBestScoreCards();
    syncAchievementsStrip();
    renderModuleSwitcher();
    renderLessonPath();
    renderHeroLesson();
    renderSavedWords();
    renderDailyGoal();
    renderSrsWidget();
    renderSeasonBanner();
    renderGameOfDayPlaque();
    renderTopikQuestionCard();
    renderContinue();
    renderBearGuide();
    applyAvatar(UStore.get('avatar'));
    updateGameSourceUI();
  }

