              return `<button onclick="adminSetPlan('${escAttrSafe(uid)}','${pid}')" class="btn ${on ? 'btn-primary' : 'btn-ghost'}" style="flex:1; padding:9px 4px; font-size:11px; ${on ? '' : 'opacity:.85;'}">${p.emoji} ${p.name}</button>`;
